  'Not checked' => 'لم يتم التحقق منها',
  'We received your receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'لقد استلمنا إيصالك، شكرًا لك 🌱 سنرد عليك بخصوص دفعتك في أقرب وقت ممكن.',
  'We received your receipt, thank you 🌱 Your donation is confirmed.' => 'لقد استلمنا إيصالك، شكرًا لك 🌱 تم تأكيد تبرعك.',
  'We had already received this receipt, thank you 🌱 We\'ll get back to you about your payment as soon as possible.' => 'لقد تلقينا هذا الإيصال بالفعل، شكرًا لك 🌱 سنرد عليك بشأن دفعتك في أقرب وقت ممكن.',
  'This receipt seems to have been uploaded to our system before. The same receipt cannot be used for a second donation. If you made a different payment, please send that receipt; our team will also check.' => 'يبدو أن هذا الإيصال قد تم تحميله إلى نظامنا من قبل. لا يمكن استخدام نفس الإيصال للتبرع الثاني. إذا قمت بإجراء دفعة مختلفة، يرجى إرسال هذا الإيصال؛ سيقوم فريقنا أيضًا بالتحقق.',
  'We received your receipt. The amount on it (%1$s) does not seem to match your donation amount (%2$s). Could you check it? If you made a different payment, you can write here; our team will also take a look.' => 'لقد تلقينا إيصالك. يبدو أن المبلغ الموجود عليه (%1$s) لا يتطابق مع مبلغ تبرعك (%2$s). هل يمكنك التحقق من ذلك؟ إذا قمت بإجراء دفعة مختلفة، يمكنك الكتابة هنا؛ سوف يقوم فريقنا أيضًا بإلقاء نظرة.',
  'We received your receipt, but the recipient on it does not seem to be our association. Donations are only made to our account in the name of "%s". Could you check? Our team will also take a look.' => 'لقد استلمنا إيصالك، ولكن لا يبدو أن المستلم هو مؤسستنا. التبرعات تتم فقط لحسابنا بإسم "%s". هل يمكنك التحقق؟ سوف يقوم فريقنا أيضًا بإلقاء نظرة.',
  'We received your receipt, but the recipient on it does not seem to match our account. Could you check? Our team will also take a look.' => 'لقد تلقينا إيصالك، ولكن يبدو أن المستلم الموجود عليه لا يتطابق مع حسابنا. هل يمكنك التحقق؟ سوف يقوم فريقنا أيضًا بإلقاء نظرة.',
  'The file you sent does not look like a payment receipt. If you have paid, you can send the receipt or a screenshot of the payment screen here.' => 'الملف الذي أرسلته لا يبدو كإيصال الدفع. إذا قمت بالدفع، يمكنك إرسال الإيصال أو لقطة شاشة لشاشة الدفع هنا.',
