  'Motivational lines (one per line; one is added at random to each report)' => 'خطوط تحفيزية (واحد في كل سطر، ويتم إضافة واحد عشوائيًا إلى كل تقرير)',
  '%d recipients (with a registered number and permission).' => 'مستلمو %d(برقم مسجل وإذن).',
  'Last sent: %s.' => 'آخر إرسال: %s.',
  'Preview (for you)' => 'المعاينة (لك)',
  'Send me a test' => 'أرسل لي اختبارا',
  'Send the report to all recipients now?' => 'هل تريد إرسال التقرير إلى كافة المستلمين الآن؟',
  'Send to everyone now' => 'أرسل للجميع الآن',
  'Delete this report?' => 'هل تريد حذف هذا التقرير؟',
  '+ New report' => '+ تقرير جديد',
  'The recipient\'s number comes from Users › Profile › WhatsApp number; permissions from Users › Roles and access (receive reports, view overall report, manage reports). Reports go out at the chosen time; without a server scheduler they are sent on the next site visit or chat panel use.' => 'يأتي رقم المستلم من المستخدمين › الملف الشخصي › رقم WhatsApp؛ الأذونات من المستخدمين › الأدوار والوصول (تلقي التقارير وعرض التقرير الشامل وإدارة التقارير). التقارير تخرج في الوقت المختار؛ بدون جدولة الخادم، يتم إرسالها عند زيارة الموقع التالية أو استخدام لوحة الدردشة.',
  'Invalid phone number.' => 'رقم الهاتف غير صالح.',
  'First add a WhatsApp connection under Settings › Connections.' => 'قم أولاً بإضافة اتصال WhatsApp ضمن الإعدادات › الاتصالات.',
  '%1$s assigned the chat to %2$s' => 'قام %1$s بتعيين الدردشة إلى %2$s',
  '%s removed the chat assignment' => 'قام %s بإزالة مهمة الدردشة',
  '%s closed the chat' => 'أغلق %s الدردشة',
  '%s reopened the chat' => 'أعاد %s فتح الدردشة',
  'File is too large (max %s).' => 'الملف كبير جدًا (الحد الأقصى لـ%s).',
  'This file type cannot be sent.' => 'لا يمكن إرسال هذا النوع من الملفات.',
  'File could not be uploaded.' => 'لا يمكن تحميل الملف.',
  'This message cannot be resent.' => 'لا يمكن إعادة إرسال هذه الرسالة.',
  'Can\'t react to this message.' => 'لا يمكن الرد على هذه الرسالة.',
  'You can only delete your own notes.' => 'يمكنك فقط حذف الملاحظات الخاصة بك.',
  'Reply text cannot be empty.' => 'لا يمكن أن يكون نص الرد فارغًا.',
  'Connection not found. Save the settings first.' => 'لم يتم العثور على الاتصال. احفظ الإعدادات أولاً.',
  'The message was only image code; it was not sent.' => 'وكانت الرسالة عبارة عن رمز صورة فقط؛ لم يتم إرساله.',
  'This contact is blocklisted; no messages are sent. Remove them from the blocklist to write again.' => 'تم إدراج جهة الاتصال هذه في القائمة المحظورة؛ يتم إرسال أية رسائل. قم بإزالتهم من قائمة الحظر للكتابة مرة أخرى.',
  'Message could not be saved.' => 'لا يمكن حفظ الرسالة.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API (version %s) could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'تكتب جهة الاتصال هذه من رقم WhatsApp مخفي (@lid) ولا يمكن إرسال Evolution API (الإصدار %s) إلى هذا العنوان. قم بتحديث خادم Evolution API إلى الإصدار 2.3 أو الأحدث؛ إذا وصل الرقم الحقيقي لجهة الاتصال، يرسل البرنامج المساعد هناك.',
  'This contact writes from a hidden WhatsApp number (@lid) and Evolution API could not send to this address. Update the Evolution API server to 2.3 or later; if the contact\'s real number arrives, the plugin sends there.' => 'تكتب جهة الاتصال هذه من رقم WhatsApp مخفي (@lid) ولا يمكن لـ Evolution API الإرسال إلى هذا العنوان. قم بتحديث خادم Evolution API إلى الإصدار 2.3 أو الأحدث؛ إذا وصل الرقم الحقيقي لجهة الاتصال، يرسل البرنامج المساعد هناك.',
  'No WhatsApp connection.' => 'لا يوجد اتصال واتس اب.',
  'Connected ✓' => 'متصل ✓',
  'Not connected (state: %s). Connect with QR.' => 'غير متصل (الحالة: %s). تواصل مع QR.',
  'Webhook points to this site ✓' => 'يشير Webhook إلى هذا الموقع ✓',
  'Evolution API version: %s' => 'إصدار واجهة برمجة تطبيقات التطور: %s',
  '(old: replies to hidden-number (@lid) contacts may fail, update to 2.3 or later)' => '(قديم: قد تفشل الردود على جهات الاتصال ذات الرقم المخفي (@lid)، قم بالتحديث إلى الإصدار 2.3 أو الأحدث)',
  'The webhook is not pointed at this site. Press "Set up webhook".' => 'لم يتم توجيه خطاف الويب إلى هذا الموقع. اضغط على "إعداد خطاف الويب".',
  'Webhook set up ✓ Incoming messages will now arrive here.' => 'تم إعداد Webhook ✓ ستصل الرسائل الواردة هنا الآن.',
  'Importing recent chats, this may take a while…' => 'جارٍ استيراد الدردشات الأخيرة، قد يستغرق ذلك بعض الوقت...',
  'Messages stored in Evolution: %s' => 'الرسائل المخزنة في Evolution: %s',
  'Evolution does not store messages, so older messages cannot be loaded. On the Evolution server set DATABASE_SAVE_DATA_NEW_MESSAGE and DATABASE_SAVE_DATA_HISTORIC to true; for older conversations, keep "Sync full history" on in the instance settings when you reconnect the line with QR.' => 'لا يقوم Evolution بتخزين الرسائل، لذا لا يمكن تحميل الرسائل الأقدم. على خادم Evolution، قم بتعيين DATABASE_SAVE_DATA_NEW_MESSAGE وDATABASE_SAVE_DATA_HISTORIC على true؛ بالنسبة للمحادثات القديمة، احتفظ بميزة "مزامنة السجل الكامل" في إعدادات المثيل عند إعادة توصيل الخط باستخدام QR.',
  '%1$s chats, %2$s messages imported ✓' => 'دردشات %1$s، استيراد رسائل %2$s✓',
  'Scan this code via WhatsApp › Linked devices › Link a device.' => 'امسح هذا الرمز ضوئيًا عبر WhatsApp › الأجهزة المرتبطة › ربط جهاز.',
  'Pairing code:' => 'رمز الاقتران:',
  'This line is already connected ✓' => 'هذا الخط متصل بالفعل ✓',
  'Save the settings first.' => 'احفظ الإعدادات أولاً.',
  'Error:' => 'خطأ:',
  'Delete this connection? Chat history is kept.' => 'هل تريد حذف هذا الاتصال؟ يتم الاحتفاظ بسجل الدردشة.',
  'Asking the AI…' => 'سؤال للذكاء الاصطناعي...',
  'Working ✓ (%2$s ms): %1$s' => 'العمل ✓ (%2$s مللي ثانية): %1$s',
  'Save the key and model first.' => 'احفظ المفتاح والطراز أولاً.',
  'Connections' => 'اتصالات',
  'Auto replies' => 'الردود التلقائية',
  'AI and assistant' => 'منظمة العفو الدولية ومساعده',
  'System check' => 'فحص النظام',
  'Connect your WhatsApp line, manage auto replies and labels.' => 'قم بتوصيل خط WhatsApp الخاص بك، وإدارة الردود التلقائية والتسميات.',
  'Open chats' => 'فتح الدردشات',
  'Settings saved.' => 'تم حفظ الإعدادات.',
  'Connections and settings the call center needs. Saved status is shown; use the "test" buttons on each tab for a live check. The same checks also appear with the other plugins on the theme\'s system-check screen.' => 'الاتصالات والإعدادات التي يحتاجها مركز الاتصال. تظهر الحالة المحفوظة. استخدم أزرار "الاختبار" في كل علامة تبويب لإجراء فحص مباشر. تظهر نفس عمليات التحقق أيضًا مع المكونات الإضافية الأخرى على شاشة فحص النظام الخاصة بالقالب.',
  'WhatsApp lines' => 'خطوط واتس اب',
  'Messages are sent and received through Evolution API. WhatsApp connections are managed in Flux Mail; choose which one to use here. The URL and API key stay there, so you do not need to update them here when they change.' => 'يتم إرسال الرسائل واستلامها من خلال Evolution API. تتم إدارة اتصالات WhatsApp في Flux Mail؛ اختر أي واحد لاستخدامه هنا. يظل عنوان URL ومفتاح واجهة برمجة التطبيقات هناك، لذا لا تحتاج إلى تحديثهما هنا عند تغييرهما.',
  'Communication › Connections' => 'الاتصالات › اتصالات',
  'Messages are sent and received via Evolution API. If an Evolution provider is set up in Flux Certificates, you can pick the same connection; the URL and API key stay there.' => 'يتم إرسال الرسائل واستلامها عبر Evolution API. إذا تم إعداد موفر التطور في شهادات Flux، فيمكنك اختيار نفس الاتصال؛ يبقى عنوان URL ومفتاح واجهة برمجة التطبيقات هناك.',
  'Add line' => 'إضافة خط',
  'Setup steps' => 'خطوات الإعداد',
  'Add the line and save.' => 'أضف السطر واحفظه.',
  'Use "Test connection" to see that Evolution is reachable. If the line is not linked, choose "Connect with QR" and scan it from the phone.' => 'استخدم "اختبار الاتصال" لمعرفة إمكانية الوصول إلى Evolution. إذا لم يكن الخط مرتبطًا، فاختر "الاتصال باستخدام QR" وقم بمسحه ضوئيًا من الهاتف.',
  'Press "Set up webhook". Incoming messages, and messages sent from the phone and from Flux Certificates, then appear here live.' => 'اضغط على "إعداد خطاف الويب". تظهر الرسائل الواردة والرسائل المرسلة من الهاتف ومن شهادات Flux هنا مباشرة.',
  'Optionally bring in past messages with "Import recent chats".' => 'قم بإحضار الرسائل السابقة بشكل اختياري من خلال "استيراد الدردشات الأخيرة".',
  'connected' => 'متصل',
  'connecting' => 'ربط',
  'not connected' => 'غير متصل',
  'not on server' => 'ليس على الخادم',
  'unreachable' => 'لا يمكن الوصول إليه',
  'Flux Mail connection: %s' => 'اتصال البريد الجريان: %s',
  'Flux Mail connection #%d (not found or disabled)' => 'اتصال Flux Mail #%d(غير موجود أو معطل)',
  'Use Flux Certificates provider: %s' => 'استخدم موفر شهادات التدفق: %s',
  'Enter separate Evolution API details' => 'أدخل تفاصيل Evolution API المنفصلة',
  'Line name (e.g. Main line)' => 'اسم الخط (على سبيل المثال الخط الرئيسي)',
  'Connection details' => 'تفاصيل الاتصال',
  'API URL' => 'عنوان URL لواجهة برمجة التطبيقات',
  'Instance name' => 'اسم المثيل',
  'API key (apikey)' => 'مفتاح واجهة برمجة التطبيقات (apikey)',
  '•••••••• (saved; type to change)' => '•••••••• (تم الحفظ؛ اكتب للتغيير)',
  'Webhook URL' => 'عنوان URL للويب هوك',
  'Regenerate secret key' => 'إعادة إنشاء المفتاح السري',
  'Last webhook: %s' => 'آخر خطاف ويب: %s',
  'No webhook received yet.' => 'لم يتم استلام الرد التلقائي على الويب حتى الآن.',
  'Test connection' => 'اتصال الاختبار',
  'Connect with QR' => 'تواصل مع QR',
  'QR, status and accounts: Communication › Connections' => 'QR والحالة والحسابات: الاتصالات › الاتصالات',
  'Set up webhook' => 'قم بإعداد خطاف الويب',
  'Import recent chats' => 'استيراد الدردشات الأخيرة',
  'The webhook URL and test buttons appear after saving.' => 'يظهر عنوان URL للخطاف على الويب وأزرار الاختبار بعد الحفظ.',
  'Appearance' => 'المظهر',
  'Panel title' => 'عنوان اللوحة',
  'Site name if empty. The {brand} variable uses this too.' => 'اسم الموقع إذا كان فارغا. يستخدم المتغير {brand} هذا أيضًا.',
  'Accent color' => 'لون مميز',
  'Behavior' => 'السلوك',
  'Send read receipts (blue ticks) when a chat is opened' => 'إرسال إيصالات القراءة (علامات التجزئة الزرقاء) عند فتح الدردشة',
  'Prefix messages with the agent\'s name (*Name:*)' => 'الرسائل البادئة باسم الوكيل (*الاسم:*)',
  'Agents see only chats assigned to them and unassigned chats (admins see all)' => 'يرى الوكلاء فقط الدردشات المخصصة لهم والمحادثات غير المخصصة (يرى المسؤولون الكل)',
  'Also show WhatsApp group messages' => 'إظهار أيضًا رسائل مجموعة WhatsApp',
  'New interface (experimental): the Chats page opens with the same screen as the desktop and mobile app' => 'الواجهة الجديدة (تجريبية): تفتح صفحة الدردشات بنفس شاشة تطبيق سطح المكتب والهاتف المحمول',
  'Live update interval (sec)' => 'الفاصل الزمني للتحديث المباشر (ثانية)',
  'Agents' => 'الوكلاء',
  'Give a user the %s role; they see only the chat screen and cannot open settings. Administrators always have access.' => 'منح المستخدم دور %s؛ لا يرون سوى شاشة الدردشة ولا يمكنهم فتح الإعدادات. يتمتع المسؤولون دائمًا بإمكانية الوصول.',
  'Add new user' => 'إضافة مستخدم جديد',
  'Data' => 'البيانات',
  'Also delete all chats, messages and media files when the plugin is deleted' => 'احذف أيضًا جميع الدردشات والرسائل وملفات الوسائط عند حذف المكون الإضافي',
  'Media files are kept in wp-content/uploads/flx-chat, closed to outside access. They move with uploads when the site is migrated.' => 'يتم حفظ ملفات الوسائط في wp-content/uploads/flx-chat، ومغلقة أمام الوصول الخارجي. وهي تتحرك مع التحميلات عند ترحيل الموقع.',
  'Mon' => 'الاثنين',
  'Tue' => 'الثلاثاء',
  'Wed' => 'الأربعاء',
  'Thu' => 'الخميس',
  'Fri' => 'الجمعة',
  'Sat' => 'جلس',
  'Sun' => 'الشمس',
  'Welcome message' => 'رسالة ترحيب',
  'Send automatically to people who write to us for the first time' => 'أرسل تلقائيًا إلى الأشخاص الذين يكتبون إلينا لأول مرة',
  'Away message' => 'رسالة بعيدا',
  'Auto reply to messages received outside business hours' => 'الرد التلقائي على الرسائل المستلمة خارج ساعات العمل',
  'Business days' => 'أيام العمل',
  'Start' => 'ابدأ',
  'End' => 'نهاية',
  'At most once per contact every (hours)' => 'مرة واحدة على الأكثر لكل جهة اتصال كل (ساعات)',
  'Timezone: %1$s. Now: %2$s.' => 'المنطقة الزمنية: %1$s. الآن: %2$s.',
  'within business hours' => 'خلال ساعات العمل',
  'outside business hours' => 'خارج ساعات العمل',
  'The {first_name}, {name}, {brand}, {site}, {date} variables can be used in the texts.' => 'يمكن استخدام متغيرات {first_name} و {name} و {brand} و {site} و {date} في النصوص.',
  'Chat labels' => 'تسميات الدردشة',
  'Label chats and filter the list (e.g. Donation, Complaint, Follow-up).' => 'قم بتسمية الدردشات وتصفية القائمة (مثل التبرع والشكوى والمتابعة).',
  'Add label' => 'إضافة تسمية',
  'Label name' => 'اسم التسمية',
  'Creating records from chats' => 'إنشاء سجلات من الدردشات',
  'Buttons in the chat header create a donation record (Flux Donate) and a certificate (Flux Certificates), and an incoming receipt is matched with a record. If a plugin is not installed, its button is hidden.' => 'تقوم الأزرار الموجودة في رأس الدردشة بإنشاء سجل تبرع (Flux Donate) وشهادة (Flux Certifieds)، وتتم مطابقة الإيصال الوارد مع السجل. إذا لم يتم تثبيت البرنامج الإضافي، فسيتم إخفاء الزر الخاص به.',
  'Agents can create donation records and match receipts' => 'يمكن للوكلاء إنشاء سجلات التبرعات ومطابقة الإيصالات',
  'Agents can create and send certificates' => 'يمكن للوكلاء إنشاء وإرسال الشهادات',
  'Show quick reply bubbles above the message box' => 'إظهار فقاعات الرد السريع أعلى مربع الرسالة',
  'Donation messages' => 'رسائل التبرع',
  'Ready texts sent to the person when a record is created (editable before sending). If left empty, the default text is used.' => 'النصوص الجاهزة تُرسل إلى الشخص عند إنشاء سجل (قابلة للتحرير قبل الإرسال). إذا تركت فارغة، يتم استخدام النص الافتراضي.',
  'Awaiting payment (promised transfer)' => 'في انتظار الدفع (التحويل الموعود)',
  'Donation received' => 'تم استلام التبرع',
  'Receipt confirmed' => 'تم تأكيد الاستلام',
  'Bank details ({bank})' => 'تفاصيل البنك ({bank})',
  'Recipient name, bank, IBAN' => 'اسم المستلم، البنك، رقم IBAN',
  'If empty, the account in WooCommerce › Payments › Bank transfer is used.' => 'إذا كان فارغًا، فسيتم استخدام الحساب في WooCommerce › المدفوعات › التحويل البنكي.',
  'Variables: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'المتغيرات: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'AI connection' => 'اتصال الذكاء الاصطناعي',
  'Keys, prompt caching, spending limits and usage logs come from the Flux AI & MCP plugin; all of the Call Center\'s AI requests go through it. Model choices stay here; if a field is empty, the model chosen for this plugin in Flux AI (or the default) is used.' => 'تأتي المفاتيح والتخزين المؤقت السريع وحدود الإنفاق وسجلات الاستخدام من البرنامج الإضافي Flux AI & MCP؛ تمر جميع طلبات الذكاء الاصطناعي الخاصة بمركز الاتصال من خلاله. تبقى خيارات النماذج هنا؛ إذا كان الحقل فارغًا، فسيتم استخدام النموذج المختار لهذا البرنامج المساعد في Flux AI (أو الافتراضي).',
  'Open Flux AI settings' => 'افتح إعدادات Flux AI',
  'AI needs the Flux AI & MCP plugin. Install and activate it, then enter the OpenRouter and/or Anthropic key in Flux AI & MCP › Settings. Until then suggestions, the assistant, receipt reading, voice messages and summaries are off.' => 'يحتاج الذكاء الاصطناعي إلى البرنامج المساعد Flux AI & MCP. قم بتثبيته وتنشيطه، ثم أدخل مفتاح OpenRouter و/أو Anthropic في إعدادات Flux AI & MCP. حتى ذلك الحين، يتم إيقاف الاقتراحات والمساعد وقراءة الإيصالات والرسائل الصوتية والملخصات.',
  'Creativity (0–1)' => 'الإبداع (0-1)',
  'Lower values give more consistent replies, higher values freer ones. 0.4 recommended.' => 'تعطي القيم المنخفضة ردودًا أكثر اتساقًا، بينما توفر القيم الأعلى إجابات أكثر حرية. 0.4 الموصى بها.',
  'Model (for suggestions)' => 'النموذج (للإقتراحات)',
  'Assistant model (optional)' => 'نموذج مساعد (اختياري)',
  'Model above' => 'النموذج أعلاه',
  'Only models that support tools are listed.' => 'يتم سرد النماذج التي تدعم الأدوات فقط.',
  'Receipt reading model (optional)' => 'نموذج قراءة الإيصال (اختياري)',
  'If the selected model cannot read images, a cheap vision model is used automatically.' => 'إذا لم يتمكن النموذج المحدد من قراءة الصور، فسيتم استخدام نموذج رؤية رخيص تلقائيًا.',
  'This month (%1$s): %2$s requests, %3$s tokens, about $%4$s.' => 'هذا الشهر (%1$s): طلبات %2$s، رموز %3$s، حوالي %4$s دولار.',
  'Reply suggestions' => 'الرد على الاقتراحات',
  'Above the message box, the next message is suggested from the conversation. The agent clicks "Send" or takes it into the box with "Edit". A suggestion is never sent on its own.' => 'أعلى مربع الرسالة، يتم اقتراح الرسالة التالية من المحادثة. ينقر الوكيل على "إرسال" أو يأخذه إلى المربع باستخدام "تحرير". لا يتم إرسال الاقتراح من تلقاء نفسه أبدًا.',
  'Prepare a suggestion automatically when the last message came from the person (if off, ask with the ✨ button)' => 'قم بإعداد اقتراح تلقائيًا عند وصول آخر رسالة من الشخص (إذا كان متوقفًا، اسأل باستخدام الزر ✨)',
  'Organization info and tone' => 'معلومات المنظمة والنبرة',
  'E.g. Our association plants saplings in Istanbul. Planting is done every year between November and March. The certificate is sent on WhatsApp after the donation. Use a warm but formal tone.' => 'على سبيل المثال جمعيتنا تزرع شتلات في اسطنبول. تتم الزراعة كل عام بين نوفمبر ومارس. يتم إرسال الشهادة على الواتساب بعد التبرع. استخدم لهجة دافئة ولكن رسمية.',
  'Suggestions and the assistant use this. Donation types, prices, bank details and quick replies are added automatically.' => 'الاقتراحات والمساعد يستخدم هذا. تتم إضافة أنواع التبرعات والأسعار والتفاصيل المصرفية والردود السريعة تلقائيًا.',
  'Suggestion provider' => 'مزود الاقتراح',
  'Donation assistant (automatic replies)' => 'مساعد التبرعات (الردود التلقائية)',
  'When on, the assistant replies itself: it greets, asks the name to address them, sends donation options and prices, optionally collects email and "in whose name", and asks for confirmation after each change. After confirmation it opens an "awaiting payment" record in Flux Donate and sends the donation link, recipient, IBAN and reference as separate messages. If the topic leaves donations, it hands the chat to the team.' => 'عند التشغيل، يقوم المساعد بالرد على نفسه: يرحب، ويطلب الاسم لمخاطبتهم، ويرسل خيارات التبرع والأسعار، ويجمع بشكل اختياري البريد الإلكتروني و"باسم من"، ويطلب التأكيد بعد كل تغيير. بعد التأكيد، يفتح سجل "في انتظار الدفع" في Flux Donate ويرسل رابط التبرع والمستلم ورقم IBAN والمرجع كرسائل منفصلة. إذا ترك الموضوع تبرعات، فسيتم تسليم الدردشة إلى الفريق.',
  'The Flux Donate plugin is not active; the assistant cannot create donation records.' => 'البرنامج المساعد Flux Donate غير نشط؛ لا يمكن للمساعد إنشاء سجلات التبرع.',
  'Instructions, documents, AI chats and test chat' => 'التعليمات والمستندات ومحادثات الذكاء الاصطناعي والدردشة التجريبية',
  'Turn on the donation assistant (untick to turn it off everywhere)' => 'قم بتشغيل مساعد التبرعات (قم بإزالة التحديد لإيقاف تشغيله في كل مكان)',
  'Which chats should it reply to' => 'ما هي الدردشات التي يجب الرد عليها؟',
  'In all chats (recommended)' => 'في جميع الدردشات (مستحسن)',
  'In chats not assigned to an agent' => 'في الدردشات التي لم يتم تعيينها لوكيل',
  'Only outside working hours' => 'فقط خارج أوقات العمل',
  'When an agent writes in a chat (from the panel or the phone), the assistant stays quiet there for the time below. Use the assistant button in the chat header to turn it on or off per chat.' => 'عندما يكتب أحد الوكلاء في محادثة (من اللوحة أو الهاتف)، يظل المساعد هادئًا هناك طوال الوقت أدناه. استخدم زر المساعد الموجود في رأس الدردشة لتشغيله أو إيقاف تشغيله لكل دردشة.',
  'Test mode: reply only to the numbers below' => 'وضع الاختبار: الرد فقط على الأرقام أدناه',
  'Test numbers' => 'أرقام الاختبار',
  'Separate with commas or new lines. Not used when test mode is off.' => 'افصل بفواصل أو أسطر جديدة. لا يُستخدم عند إيقاف تشغيل وضع الاختبار.',
  'Quiet after an agent writes (hours)' => 'هادئ بعد أن يكتب الوكيل (ساعات)',
  'Quantities in the price list' => 'الكميات في قائمة الأسعار',
  'Conversation history (hours)' => 'سجل المحادثات (ساعات)',
  'Before replying, the assistant reads all messages from this period.' => 'قبل الرد، يقرأ المساعد جميع الرسائل من هذه الفترة.',
  'Donation types the assistant offers' => 'أنواع التبرعات التي يقدمها المساعد',
  'If none is selected, all open types are offered. When a new type is opened in Flux Donate, the assistant knows it too.' => 'إذا لم يتم تحديد أي شيء، فسيتم عرض كافة الأنواع المفتوحة. عند فتح نوع جديد في Flux Donate، يعرف المساعد ذلك أيضًا.',
  'Receipt pre-check: when the contact sends a receipt, AI compares the amount, recipient and IBAN with the donation, tells the contact the result, attaches the file to the donation record and hands the chat to the team for final approval (does not mark it paid)' => 'التحقق المسبق من الاستلام: عندما ترسل جهة الاتصال إيصالاً، يقارن الذكاء الاصطناعي المبلغ والمستلم ورقم الحساب المصرفي الدولي مع التبرع، ويخبر جهة الاتصال بالنتيجة، ويرفق الملف بسجل التبرع ويسلم الدردشة إلى الفريق للحصول على الموافقة النهائية (لا يتم وضع علامة على أنها مدفوعة)',
  'Last line of the price list' => 'السطر الأخير من قائمة الأسعار',
  'Payment details' => 'تفاصيل الدفع',
  'If the recipient and IBAN are empty, those in WooCommerce › Payments › Bank transfer are used (the account shown on orders). Fill them in only if the assistant should use a different account.' => 'إذا كان المستلم ورقم IBAN فارغين، فسيتم استخدام تلك الموجودة في WooCommerce › المدفوعات › التحويل البنكي (الحساب الموضح في الطلبات). املأها فقط إذا كان على المساعد استخدام حساب مختلف.',
  'Recipient name' => 'اسم المستلم',
  'Transfer description' => 'وصف النقل',
  'Variables: {type}, {name}, {amount}, {quantity}' => 'المتغيرات: {type}، {name}، {amount}، {quantity}',
  'Donation page URL' => 'عنوان URL لصفحة التبرع',
  'The selected type and quantity are added to the link (?flxb_opt=…&flxb_qty=…).' => 'يتم إضافة النوع والكمية المحددة إلى الرابط (?flxb_opt=...&flxb_qty=...).',
  'Message after the payment details' => 'رسالة بعد تفاصيل الدفع',
  'Donation cancellation question' => 'سؤال إلغاء التبرع',
  'The assistant cancels only unpaid donations, with the person\'s confirmation. Empty = default text. Variables: {bagis}, {tutar}.' => 'يقوم المساعد بإلغاء التبرعات غير المدفوعة فقط، مع تأكيد الشخص. فارغ = النص الافتراضي. المتغيرات: {bagis}، {tutar}.',
  'Message sent when the daily limit is reached' => 'يتم إرسال الرسالة عند الوصول إلى الحد اليومي',
  'Sent once when a chat reaches the day\'s reply limit; the chat is handed to the team. Reset it from the chat\'s ⋮ menu › Assistant usage.' => 'يتم إرساله مرة واحدة عندما تصل الدردشة إلى حد الرد اليومي؛ يتم تسليم الدردشة إلى الفريق. أعد ضبطه من قائمة الدردشة ⋮ › استخدام المساعد.',
  'Message sent when handing over to the team' => 'تم إرسال الرسالة عند التسليم للفريق',
  'Message sent when the assistant cannot answer' => 'يتم إرسال الرسالة عندما لا يتمكن المساعد من الرد',
  'If the AI fails, the time limit is hit or the queue gets too long, this message is sent and the chat is handed to the team; the person is never left without an answer.' => 'إذا فشل الذكاء الاصطناعي، أو تم الوصول إلى الحد الزمني أو أصبحت قائمة الانتظار طويلة جدًا، فسيتم إرسال هذه الرسالة وتسليم الدردشة إلى الفريق؛ لا يترك الشخص أبدًا بدون إجابة.',
  'Minimum wait before the holding message (s)' => 'الحد الأدنى للانتظار قبل الرسالة (الرسائل) المعلقة',
  'The holding message is not sent until this many seconds after the person\'s message; meanwhile the assistant retries.' => 'لا يتم إرسال الرسالة المعلقة إلا بعد عدة ثوانٍ من رسالة الشخص؛ وفي الوقت نفسه يقوم المساعد بإعادة المحاولة.',
  'Longest time for one answer (s)' => 'أطول وقت لإجابة واحدة (إجابات)',
  'Hostinger can cut requests at ~60 s; 50 is recommended.' => 'يمكن لـ Hostinger قطع الطلبات في حوالي 60 ثانية؛ يوصى بـ 50.',
  'Numbers notified on handoff' => 'تم إخطار الأرقام عند التسليم',
  'When the assistant hands a chat over to the team, a WhatsApp message is sent to these numbers from the same line: the contact\'s name, phone, reason, last messages and panel link. Separate with commas or new lines. The assistant does not talk to these numbers.' => 'عندما يقوم المساعد بتسليم الدردشة إلى الفريق، يتم إرسال رسالة WhatsApp إلى هذه الأرقام من نفس السطر: اسم جهة الاتصال والهاتف والسبب والرسائل الأخيرة ورابط اللوحة. افصل بفواصل أو أسطر جديدة. المساعد لا يتحدث مع هذه الأرقام.',
  'When the contact writes one of these, the assistant immediately sends the hand-off message above and turns off in that chat. If left empty, the example list is used.' => 'عندما تكتب جهة الاتصال إحدى هذه الرسائل، يرسل المساعد على الفور رسالة التسليم أعلاه ويتم إيقاف تشغيله في تلك الدردشة. إذا تركت فارغة، يتم استخدام قائمة الأمثلة.',
  'Extra instructions for the assistant' => 'تعليمات اضافية للمساعد',
  'E.g. Saplings are planted in Kocaeli. Certificates are sent once the donation is confirmed.' => 'على سبيل المثال يتم زرع الشتلات في قوجه ايلي. يتم إرسال الشهادات بمجرد تأكيد التبرع.',
  'Last message when a contact opts out' => 'الرسالة الأخيرة عندما تقوم جهة اتصال بإلغاء الاشتراك',
  'If someone writes something like "don\'t message me", the assistant sends this message and blocklists them. A blocklisted person gets no WhatsApp, email or SMS; manage the list under Chats › ☰ › Blocklist.' => 'إذا كتب شخص ما شيئًا مثل "لا تراسلني"، فسيرسل المساعد هذه الرسالة ويضعه في قائمة الحظر. لا يحصل الشخص المدرج في القائمة المحظورة على تطبيق WhatsApp أو البريد الإلكتروني أو الرسائل النصية القصيرة؛ قم بإدارة القائمة ضمن الدردشات › ☰ › قائمة الحظر.',
  'Contact memory and background jobs' => 'ذاكرة الاتصال ووظائف الخلفية',
  'Contact memory: the assistant remembers lasting details (form of address, relatives\' names, numbers, preferences); expired chats are summarized' => 'ذاكرة الاتصال: يتذكر المساعد التفاصيل الدائمة (شكل العنوان وأسماء الأقارب والأرقام والتفضيلات)؛ يتم تلخيص الدردشات منتهية الصلاحية',
  'Summarize a chat after it has been quiet for (hours)' => 'تلخيص محادثة بعد أن كانت هادئة لمدة (ساعات)',
  'Maximum jobs at the same time' => 'الحد الأقصى من الوظائف في نفس الوقت',
  'How many people can be answered at the same time. Assistant replies always come first; summaries do not start while someone is being answered or waiting. Each job uses one PHP worker: on shared hosting, stay under half of the total worker limit of your sites (e.g. 20-30 of 60 workers).' => 'كم شخص يمكن الرد عليه في نفس الوقت. تأتي ردود المساعد دائمًا في المقام الأول؛ لا تبدأ الملخصات أثناء الرد على شخص ما أو انتظاره. تستخدم كل وظيفة عامل PHP واحدًا: في الاستضافة المشتركة، ابق أقل من نصف الحد الإجمالي للعمال في مواقعك (على سبيل المثال، 20-30 من 60 عاملاً).',
  'Workers reserved for replies' => 'العمال محفوظة للردود',
  'This many workers never take summaries or reminders.' => 'هذا العدد من العمال لا يأخذون ملخصات أو تذكيرات أبدًا.',
  'Summary hours' => 'ساعات الملخص',
  'Summaries run only between these hours (except a manual "Summarize now"). If both are the same, any time.' => 'يتم تشغيل الملخصات فقط بين هذه الساعات (باستثناء دليل "التلخيص الآن"). إذا كان كلاهما هو نفسه، في أي وقت.',
  'When someone sends a voice message, the assistant turns it into text and replies (the text also appears in the panel as a system line)' => 'عندما يرسل شخص ما رسالة صوتية، يقوم المساعد بتحويلها إلى نص والردود (يظهر النص أيضًا في اللوحة كخط نظام)',
  'Longest voice message (sec)' => 'أطول رسالة صوتية (ثانية)',
  'For longer messages the assistant says "the voice message was too long for us to listen to".' => 'بالنسبة للرسائل الأطول، يقول المساعد "كانت الرسالة الصوتية طويلة جدًا بالنسبة لنا للاستماع إليها".',
  'Voice message model (optional)' => 'نموذج الرسالة الصوتية (اختياري)',
  'Cheap audio model (Gemini Flash Lite)' => 'نموذج صوتي رخيص (Gemini Flash Lite)',
  'Must be an OpenRouter model that accepts audio (Claude does not). An OpenRouter key is required.' => 'يجب أن يكون نموذج OpenRouter يقبل الصوت (كلود لا يقبل ذلك). مطلوب مفتاح OpenRouter.',
  'Images' => 'الصور',
  'Let the assistant draw an image when useful (table, report, diagram); it goes to WhatsApp as a picture, the text is sent separately' => 'اسمح للمساعد برسم صورة عندما يكون ذلك مفيدًا (جدول، تقرير، رسم تخطيطي)؛ فإنه يذهب إلى WhatsApp كصورة، ويتم إرسال النص بشكل منفصل',
  'The Flux AI image renderer is used (Flux AI & MCP › Settings › Images).' => 'يتم استخدام عارض الصور Flux AI (Flux AI & MCP ›الإعدادات› الصور).',
  'No image renderer on the server: enter a Gotenberg address in Flux AI & MCP › Settings › Images or install Imagick (SVG). Until then the assistant does not draw images.' => 'لا يوجد عارض صور على الخادم: أدخل عنوان Gotenberg في Flux AI & MCP ›الإعدادات› الصور أو قم بتثبيت Imagick (SVG). وحتى ذلك الحين لا يرسم المساعد الصور.',
  'Works once Flux AI 0.2.0 or later is installed.' => 'يعمل بمجرد تثبيت Flux AI 0.2.0 أو الأحدث.',
  'Donation on behalf of someone' => 'التبرع نيابة عن شخص ما',
  'If the donation is in someone else\'s name and their number was given (contact card or typed number), also send the certificate to that number on WhatsApp once the payment is approved' => 'إذا كان التبرع باسم شخص آخر وتم إعطاء رقمه (بطاقة الاتصال أو الرقم المكتوب)، قم أيضًا بإرسال الشهادة إلى هذا الرقم على الواتساب بمجرد الموافقة على الدفع',
  'Message sent before the certificate' => 'الرسالة المرسلة قبل الشهادة',
  'Then the WhatsApp certificate message from Flux Certificates is sent. Variables: {ad}, {bagisci}, {bagis}, {brand}.' => 'ثم يتم إرسال رسالة شهادة WhatsApp من شهادات Flux. المتغيرات: {ad}, {bagisci}, {bagis}, {brand}.',
  'If a person asks, the assistant sets up a reminder (e.g. "remind me of sapling planting every month", "send me your latest projects every month", "ask me for a sapling every month"); when it is due, the assistant writes and sends the message' => 'إذا سأل شخص ما، يقوم المساعد بإعداد تذكير (على سبيل المثال، "ذكرني بزراعة شتلات كل شهر"، "أرسل لي أحدث مشاريعك كل شهر"، "اسألني عن شتلة كل شهر")؛ عندما يحين موعدها، يقوم المساعد بكتابة الرسالة وإرسالها',
  'When no time is given' => 'عندما لا يعطى الوقت',
  'At most per person' => 'على الأكثر للشخص الواحد',
  'Staff (Flux Roles)' => 'طاقم العمل (أدوار التدفق)',
  'Works once Flux Roles 1.1.0 is installed: users whose number is set in Profile › WhatsApp number get extra assistant tools based on their permissions.' => 'يعمل بمجرد تثبيت Flux roles 1.1.0: يحصل المستخدمون الذين تم تعيين أرقامهم في ملف التعريف › رقم WhatsApp على أدوات مساعدة إضافية بناءً على أذوناتهم.',
  'Give staff numbers extra assistant tools by permission (donation on behalf of someone with payment link, my donors, general report)' => 'منح أرقام الموظفين أدوات مساعدة إضافية عن طريق الإذن (التبرع نيابة عن شخص لديه رابط الدفع، الجهات المانحة، التقرير العام)',
  'Notify staff on WhatsApp when a donation they referred is paid or cancelled' => 'قم بإخطار الموظفين عبر تطبيق WhatsApp عندما يتم دفع أو إلغاء التبرع الذي أحالوه',
  'First message to the donor for a donation opened by staff' => 'الرسالة الأولى إلى المتبرع بالتبرع يفتحها الموظفون',
  'Hello {ad} 🌱 Your {bagis} donation request via {personel} has been received. You can pay with the details below.' => 'مرحبًا {ad}🌱 لقد تم استلام طلب التبرع بـ{bagis} عبر {personel}. يمكنك الدفع بالتفاصيل أدناه.',
  'The payment link and bank details follow. Variables: {ad}, {adsoyad}, {personel}, {bagis}.' => 'اتبع رابط الدفع والتفاصيل المصرفية. المتغيرات: {ad}, {adsoyad}, {personel}, {bagis}.',
  'When a donation referred by a staff member is paid and its certificates are made, send them to the staff member on WhatsApp too (just like the donor)' => 'عند دفع التبرع المحول من أحد الموظفين وإصدار شهاداته، أرسلها إلى الموظف على الواتساب أيضًا (تمامًا مثل المتبرع)',
  'Message sent to the staff member before the certificate' => 'الرسالة المرسلة للموظف قبل الشهادة',
  'Variables: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'المتغيرات: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'How many times staff can resend a donation\'s certificate' => 'كم مرة يمكن للموظفين إعادة إرسال شهادة التبرع',
  'The assistant lists the recipients and asks for confirmation before sending. 0: off.' => 'يقوم المساعد بإدراج المستلمين ويطلب التأكيد قبل الإرسال. 0: إيقاف.',
  'Code verification for record lookups' => 'التحقق من الكود لعمليات البحث عن السجلات',
  'When a person asks for their records and their number is hidden (or they donated with another number/e-mail), send a code to the number or e-mail they give; once verified, its records are shown too' => 'عندما يطلب شخص ما سجلاته ويكون رقمه مخفيًا (أو تبرع برقم/بريد إلكتروني آخر)، أرسل رمزًا إلى الرقم أو البريد الإلكتروني الذي يقدمه؛ وبمجرد التحقق منها، تظهر سجلاتها أيضًا',
  'Code validity (min)' => 'صلاحية الكود (دقيقة)',
  'Maximum failed attempts' => 'الحد الأقصى للمحاولات الفاشلة',
  'Codes that could not be sent, wrong codes and expired codes count. At the limit the person gets the message below and the team is notified; the assistant keeps answering other questions but shares no record details for 24 hours.' => 'الرموز التي لا يمكن إرسالها، يتم احتساب الرموز الخاطئة والرموز منتهية الصلاحية. عند الحد يحصل الشخص على الرسالة أدناه ويتم إخطار الفريق؛ يستمر المساعد في الإجابة على الأسئلة الأخرى ولكنه لا يشارك تفاصيل السجل لمدة 24 ساعة.',
  'Code to phone' => 'الرمز إلى الهاتف',
  'WhatsApp, SMS if it fails' => 'WhatsApp، SMS إذا فشل',
  'WhatsApp only' => 'واتساب فقط',
  'SMS only' => 'الرسائل القصيرة فقط',
  'SMS is used if Flux Mail has an SMS connection (e.g. Netgsm).' => 'يتم استخدام الرسائل القصيرة إذا كان لدى Flux Mail اتصال عبر الرسائل القصيرة (مثل Netgsm).',
  'Message when verification fails' => 'رسالة عند فشل التحقق',
  'WhatsApp/SMS code message' => 'رسالة رمز WhatsApp/SMS',
  'Default text if empty. Variables: {kod}, {dk}, {marka}. The e-mail text is edited in Flux Mail › E-mail templates.' => 'النص الافتراضي إذا كان فارغا. المتغيرات: {kod}، {dk}، {marka}. يتم تحرير نص البريد الإلكتروني في Flux Mail › قوالب البريد الإلكتروني.',
  'Site content' => 'محتوى الموقع',
  'Let the assistant search published site content (e.g. "do you have a post about tree planting")' => 'اسمح للمساعد بالبحث في محتوى الموقع المنشور (على سبيل المثال، "هل لديك مشاركة حول زراعة الأشجار")',
  'Content types to search' => 'أنواع المحتوى للبحث',
  'Only published content without a password is returned. Drafts, private and password-protected content are never shown.' => 'يتم إرجاع المحتوى المنشور فقط بدون كلمة مرور. لا يتم عرض المسودات والمحتوى الخاص والمحمي بكلمة مرور أبدًا.',
  'Categories and tags never to share' => 'الفئات والعلامات التي لا ينبغي مشاركتها مطلقًا',
  'e.g. corporate-offers, internal-notice' => 'على سبيل المثال عروض الشركات، والإشعار الداخلي',
  'Name or slug, comma separated. To hide a single item, tick "Do not let the assistant share this content" on its edit screen.' => 'الاسم أو سبيكة مفصولة بفواصل. لإخفاء عنصر واحد، حدد "عدم السماح للمساعد بمشاركة هذا المحتوى" في شاشة التحرير الخاصة به.',
  'Team group' => 'مجموعة الفريق',
  'WhatsApp group' => 'مجموعة الواتساب',
  '— Not selected —' => '— غير محدد —',
  'Groups the line is a member of. If a group you just created is missing,' => 'المجموعات التي ينتمي إليها الخط. إذا كانت المجموعة التي أنشأتها للتو مفقودة،',
  'refresh the list' => 'تحديث القائمة',
  'Post incoming messages and replies (assistant, team, automatic) to this group' => 'نشر الرسائل والردود الواردة (مساعد، فريق، تلقائي) لهذه المجموعة',
  'Send handoff notifications to this group instead of each number; the numbers above are mentioned in the message' => 'إرسال إشعارات التسليم إلى هذه المجموعة بدلاً من كل رقم؛ الأرقام المذكورة أعلاه مذكورة في الرسالة',
  'Last post to the group failed: ' => 'فشل آخر مشاركة في المجموعة:',
  'Price list preview' => 'معاينة قائمة الأسعار',
  'Enter an AI key and model first so the assistant can work.' => 'أدخل مفتاح الذكاء الاصطناعي والنموذج أولاً حتى يتمكن المساعد من العمل.',
  'The assistant will not reply right now: ' => 'لن يقوم المساعد بالرد الآن:',
  'WhatsApp assistant' => 'مساعد واتس اب',
  'Do not let the assistant share this content' => 'لا تسمح للمساعد بمشاركة هذا المحتوى',
  'Corrected by staff member %1$s; #%2$d was opened instead.' => 'تم التصحيح بواسطة الموظف %1$s؛ # تم فتح %2$d بدلاً من ذلك.',
  'Donation #%1$d was cancelled and #%2$d opened instead.' => 'تم إلغاء التبرع #%1$d وتم فتح #%2$d بدلاً منه.',
  'Created by staff member %s via the WhatsApp assistant.' => 'تم إنشاؤه بواسطة الموظف %s عبر مساعد WhatsApp.',
  'Donation opened via staff member %1$s: %2$s (#%3$d)' => 'تم فتح التبرع عن طريق الموظف %1$s: %2$s(#%3$d)',
  'Your certificate 🌱' => 'شهادتك 🌱',
  'Staff member %1$s resent the certificate on WhatsApp: %2$s' => 'استاء عضو فريق العمل %1$s من الشهادة على WhatsApp: %2$s',
  '✅ Your donor paid: *%1$s* · %2$s #%3$d' => '✅ دفع المتبرع الخاص بك: *%1$s* ·%2$s#%3$d',
  '❌ Donation cancelled: *%1$s* · %2$s #%3$d' => '❌ تم إلغاء التبرع: *%1$s* ·%2$s#%3$d',
  'Sticker' => 'ملصق',
  'Poll' => 'استطلاع',
  'Unsupported message' => 'رسالة غير مدعومة',
  '{a} lines added, {d} lines removed' => 'تمت إضافة خطوط {a}، وإزالة خطوط {d}',
  'No AI key or model has been entered.' => 'لم يتم إدخال أي مفتاح أو نموذج AI.',
  'The assistant is off and does not reply to incoming messages.' => 'المساعد متوقف ولا يرد على الرسائل الواردة.',
  'Test mode is on: the assistant only replies to test numbers.' => 'وضع الاختبار قيد التشغيل: يقوم المساعد بالرد فقط على أرقام الاختبار.',
  'Assistant activity summary' => 'ملخص نشاط المساعد',
  'Hide details' => 'إخفاء التفاصيل',
  'Details' => 'التفاصيل',
  'Spend (USD)' => 'الإنفاق (بالدولار الأمريكي)',
  'Questions answered' => 'تمت الإجابة على الأسئلة',
  'People answered' => 'أجاب الناس',
  'People directed to donate' => 'توجه الناس للتبرع',
  'Donation records created' => 'تم إنشاء سجلات التبرع',
  'Confirmed donations · {a}' => 'التبرعات المؤكدة ·{a}',
  'Receipts read · ✓{a} ✕{b}' => 'قراءة الإيصالات · ✓{a}✕{b}',
  'Memory tokens · {p} contacts' => 'رموز الذاكرة · جهات اتصال {p}',
  'Opted out (blocklist)' => 'تم التعطيل (القائمة المحظورة)',
  'Reminders sent' => 'تم إرسال التذكيرات',
  'Codes sent · e-mail {e} · WhatsApp {w} · SMS {s}' => 'تم إرسال الرموز · البريد الإلكتروني {e}· WhatsApp {w}· الرسائل القصيرة {s}',
  'Verified · phone {p} · e-mail {e}' => 'تم التحقق منه · الهاتف {p}· البريد الإلكتروني {e}',
  'Code issues · wrong {w} · expired {x} · not delivered {f}' => 'مشاكل في الكود · خطأ {w}· انتهت صلاحية {x}· لم يتم التسليم {f}',
  'Not verified, team notified' => 'لم يتم التحقق، تم إخطار الفريق',
  'Certificates resent' => 'الشهادات مستاءة',
  'Donations cancelled by the assistant' => 'تم إلغاء التبرعات من قبل المساعد',
  'Payment links resent' => 'روابط الدفع مستاءة',
  'Tokens: {i} input / {o} output · {c} requests · {m} messages sent' => 'الرموز: إدخال {i}/ إخراج {o}· طلبات {c}· إرسال رسائل {m}',
  '{n} donations awaiting payment' => 'تبرعات {n} في انتظار الدفع',
  '{n} errors' => 'أخطاء {n}',
  '{n} chats summarized' => 'تلخيص محادثات {n}',
  'Counters since {d}' => 'عدادات منذ {d}',
  'Refreshes every 30 s' => 'يتم تحديثه كل 30 ثانية',
  'Models' => 'نماذج',
  'Contacts with the most memory' => 'جهات الاتصال ذات الذاكرة الأكبر',
  'Tokens' => 'الرموز',
  'Daily' => 'يوميا',
  'No records in this range.' => 'لا توجد سجلات في هذا النطاق.',
  'Replies' => 'الردود',
  'Handoff' => 'تسليم',
  'Only real chats are counted; test chat and benchmark are excluded. "Confirmed" means donations created by the assistant and marked paid.' => 'يتم احتساب الدردشات الحقيقية فقط؛ يتم استبعاد الدردشة الاختبارية والمعيارية. "مؤكد" يعني التبرعات التي أنشأها المساعد وتم وضع علامة "مدفوعة".',
  'With the team / paused' => 'مع الفريق / متوقف',
  'Donation record created' => 'تم إنشاء سجل التبرع',
  'The assistant has not replied to any chat yet.' => 'لم يرد المساعد على أي محادثة حتى الآن.',
  'Load more' => 'تحميل المزيد',
  'Address: {h}' => 'العنوان: {h}',
  '{n} assistant messages' => 'رسائل مساعد {n}',
  'Donation #{id}' => 'التبرع #{id}',
  'Version {id}' => 'الإصدار {id}',
  'Change note (e.g. Added sacrifice question)' => 'تغيير الملاحظة (على سبيل المثال، سؤال التضحية المضافة)',
  'Assistant instructions' => 'تعليمات مساعد',
  'The main text describing how the assistant talks and the flow. Prices, donation types, bank details and what is known about the contact are added automatically on every reply. {brand} becomes the organisation name and {{belge:kisa-ad}} becomes that document\'s content.' => 'النص الرئيسي يصف كيفية تحدث المساعد وتدفقه. تتم إضافة الأسعار وأنواع التبرعات والتفاصيل المصرفية وما هو معروف عن جهة الاتصال تلقائيًا عند كل رد.  يصبح {brand} اسم المؤسسة ويصبح {{belge:kisa-ad}} محتوى ذلك المستند.',
  'Publish now' => 'انشر الآن',
  'New version saved' => 'تم حفظ النسخة الجديدة',
  'Save as new version' => 'حفظ كإصدار جديد',
  'Show the full text sent to the model' => 'إظهار النص الكامل المرسل إلى النموذج',
  'Unsaved text' => 'نص غير محفوظ',
  'Test with this text' => 'اختبار مع هذا النص',
  'Versions' => 'الإصدارات',
  'Live' => 'مباشر',
