  'No runs yet; default estimate: ~{i} input / {o} output tokens per donor message.' => 'لا يوجد تشغيل بعد؛ التقدير الافتراضي: ~ رموز الإدخال {i}/ رموز الإخراج {o} لكل رسالة مانحة.',
  'The estimate exceeds the cost limit; the run stops when the limit is reached.' => 'يتجاوز التقدير حد التكلفة؛ يتوقف التشغيل عند الوصول إلى الحد الأقصى.',
  'New run' => 'تشغيل جديد',
  'Scenarios are played like in the test chat: no WhatsApp message is sent and no record is created. The model is really called; the cost is charged to your AI account (OpenRouter or Anthropic) and the run stops when the limit is reached.' => 'يتم تشغيل السيناريوهات كما هو الحال في الدردشة التجريبية: لا يتم إرسال أي رسالة عبر WhatsApp ولا يتم إنشاء أي سجل. النموذج يسمى حقا؛ يتم تحميل التكلفة على حساب AI الخاص بك (OpenRouter أو Anthropic) ويتوقف التشغيل عند الوصول إلى الحد الأقصى.',
