  'E.g. payment_info, cancel_donation, receipt_check. Tools disabled on this site are not checked.' => 'على سبيل المثال معلومات الدفع، إلغاء_التبرع، استلام_التحقق. لم يتم التحقق من الأدوات المعطلة على هذا الموقع.',
