  'The scenario runs isolated like the test chat; what you select here exists only in this test. In a customer message, {kod} becomes the verification code from the test panel.' => 'يتم تنفيذ السيناريو بشكل معزول مثل الدردشة التجريبية؛ ما تحدده هنا موجود فقط في هذا الاختبار. في رسالة العميل، يصبح {kod} هو رمز التحقق من لوحة الاختبار.',
  'End state' => 'نهاية الحالة',
  'When the conversation ends, the test state is checked (was a donation opened, canceled, a code sent…). Tools disabled on this site are not checked.' => 'عند انتهاء المحادثة، يتم التحقق من حالة الاختبار (هل تم فتح التبرع، أو إلغاؤه، أو إرسال الرمز...). لم يتم التحقق من الأدوات المعطلة على هذا الموقع.',
  'Judge criterion' => 'معيار القاضي',
  'If empty, the judge is not called. Put quality expectations that cannot be written as rules here.' => 'إذا كان فارغا، لا يتم استدعاء القاضي. ضع توقعات الجودة التي لا يمكن كتابتها كقواعد هنا.',
  'Message written by the assistant' => 'رسالة كتبها المساعد',
  'Message written by the customer' => 'الرسالة المكتوبة من قبل العميل',
  'Drag to reorder' => 'اسحب لإعادة الترتيب',
  'Change author' => 'تغيير المؤلف',
  'Delete message' => 'حذف الرسالة',
