  'E.g. Add one more message: the person does not want to give an email.' => 'على سبيل المثال أضف رسالة أخرى: الشخص لا يريد إرسال بريد إلكتروني.',
  'E.g. The person asks about a sacrifice donation; the assistant hands off to the team without making anything up.' => 'على سبيل المثال يسأل الشخص عن التبرع بالأضحية؛ يسلم المساعد الفريق دون اختلاق أي شيء.',
  'Write' => 'اكتب',
