  'Call Center · AI' => 'مركز الاتصال · الذكاء الاصطناعي',
  'Database tables' => 'جداول قاعدة البيانات',
  'Missing table: %s. Deactivate and reactivate the plugin.' => 'الجدول المفقود: %s. قم بإلغاء تنشيط البرنامج المساعد وإعادة تنشيطه.',
  'Tables ready (schema %s).' => 'الجداول جاهزة (مخطط %s).',
  'Schema update pending; it completes when you open a page in the admin panel.' => 'تحديث المخطط معلق؛ يكتمل عند فتح صفحة في لوحة الإدارة.',
  'Media folder' => 'مجلد الوسائط',
  'Cannot write to uploads/flx-chat; incoming photos, voice notes and documents cannot be saved. Check folder permissions.' => 'لا يمكن الكتابة إلى التحميلات/flx-chat؛ لا يمكن حفظ الصور والملاحظات الصوتية والمستندات الواردة. تحقق من أذونات المجلد.',
  'Folder protection (.htaccess) missing; it is created with the first saved media.' => 'حماية المجلد (.htaccess) مفقودة؛ يتم إنشاؤه باستخدام الوسائط المحفوظة الأولى.',
