  'Available.' => 'متاح.',
  'Missing; while the assistant prepares a reply the "typing…" indicator shows only briefly.' => 'مفقود؛ بينما يقوم المساعد بإعداد الرد، يظهر مؤشر "الكتابة..." لفترة وجيزة فقط.',
  'Users with the agent role: %d.' => 'المستخدمون الذين لديهم دور الوكيل: %d.',
  'No user has the agent role; only administrators can use it for now.' => 'لا يوجد مستخدم لديه دور الوكيل؛ يمكن للمسؤولين فقط استخدامه في الوقت الحالي.',
  'Live panel updates' => 'تحديثات اللوحة الحية',
  'The chat screen has not been opened yet.' => 'شاشة الدردشة لم تفتح بعد.',
  'WhatsApp line' => 'خط واتس اب',
  'No line added.' => 'لم تتم إضافة أي سطر.',
  '%s: connection details' => '%s: تفاصيل الاتصال',
  'Using Flux Mail connection: %s.' => 'استخدام اتصال Flux Mail: %s.',
  'Still using the old provider in Flux Certificates; move the connection to Flux Mail and select it here.' => 'لا تزال تستخدم الموفر القديم في شهادات التدفق؛ انقل الاتصال إلى Flux Mail وحدده هنا.',
  'Using the Evolution provider from Flux Certificates.' => 'استخدام موفر التطور من شهادات التدفق.',
  'API URL, key and instance are entered in this plugin.' => 'يتم إدخال عنوان URL لواجهة برمجة التطبيقات والمفتاح والمثيل في هذا البرنامج المساعد.',
  '%s: line status' => '%s: حالة الخط',
  'Phone connected (last seen %s).' => 'الهاتف متصل (شوهد آخر مرة %s).',
  'Not tested yet. Press "Test connection".' => 'لم يتم اختباره بعد. اضغط على "اختبار الاتصال".',
  'Phone not connected (state: %1$s, %2$s). Reconnect with "Connect with QR".' => 'الهاتف غير متصل (الحالة: %1$s، %2$s). أعد الاتصال بـ "الاتصال بـ QR".',
  '%s: Evolution API version' => '%s: إصدار Evolution API',
  'Evolution API %s is in use. Replies to hidden-number (@lid) contacts may fail; update the server to 2.3 or later.' => 'Evolution API %s قيد الاستخدام. قد تفشل الردود على جهات الاتصال ذات الرقم المخفي (@lid)؛ تحديث الخادم إلى 2.3 أو الأحدث.',
  '%s: webhook (incoming messages)' => '%s: خطاف الويب (الرسائل الواردة)',
  'No events have arrived from Evolution; incoming messages will not show in the panel. Press "Set up webhook".' => 'لم تصل أي أحداث من التطور؛ لن تظهر الرسائل الواردة في اللوحة. اضغط على "إعداد خطاف الويب".',
  'Last event arrived %s. The line may just be quiet; send yourself a message or set up the webhook again to be sure.' => 'الحدث الأخير وصل %s. قد يكون الخط هادئًا فحسب؛ أرسل لنفسك رسالة أو قم بإعداد خطاف الويب مرة أخرى للتأكد.',
  'Last event arrived %s.' => 'الحدث الأخير وصل %s.',
  'Flux Mail integration' => 'تكامل البريد الجريان',
  'Active: WhatsApp connections are taken from Communication › Connections.' => 'نشط: اتصالات WhatsApp مأخوذة من الاتصالات › الاتصالات.',
  'Flux Mail is not active; connections are taken from Flux Certificates or from this plugin.' => 'Flux Mail غير نشط؛ يتم أخذ الاتصالات من شهادات Flux أو من هذا البرنامج المساعد.',
  'Flux Certificates integration' => 'تكامل شهادات التدفق',
  'Active: certificates can be created and sent from chats.' => 'نشط: يمكن إنشاء الشهادات وإرسالها من الدردشات.',
  'Flux Certificates is not active; certificate actions in chats are off.' => 'شهادات التدفق غير نشطة؛ إجراءات الشهادة في الدردشات متوقفة.',
  'Flux Donate integration' => 'تدفق التبرع التكامل',
  'Active: donation records, receipt matching and the assistant are available from chats.' => 'نشط: تتوفر سجلات التبرعات ومطابقة الإيصالات والمساعد من الدردشات.',
  'Flux Donate is not active; donation records, receipt matching and the donation assistant are off.' => 'Flux Donate غير نشط؛ سجلات التبرعات ومطابقة الإيصالات ومساعد التبرعات متوقفة.',
  'The Flux AI & MCP plugin is not installed; AI features (suggestions, assistant, receipt reading, voice messages, summaries) are off. Install Flux AI and enter the key there.' => 'لم يتم تثبيت البرنامج المساعد Flux AI & MCP؛ ميزات الذكاء الاصطناعي (الاقتراحات، المساعد، قراءة الإيصالات، الرسائل الصوتية، الملخصات) متوقفة. قم بتثبيت Flux AI وأدخل المفتاح هناك.',
  'No key has been entered in Flux AI; message suggestions and the assistant are off.' => 'لم يتم إدخال أي مفتاح في Flux AI؛ اقتراحات الرسائل والمساعد متوقفان.',
  'Key saved but no model selected.' => 'تم حفظ المفتاح ولكن لم يتم تحديد نموذج.',
  'No provider key has been entered in Flux AI for the selected model (%s).' => 'لم يتم إدخال أي مفتاح موفر في Flux AI للنموذج المحدد (%s).',
  'Key saved, model: %s. Use "Test connection" for a live check.' => 'تم حفظ المفتاح، الموديل: %s. استخدم "اختبار الاتصال" لإجراء فحص مباشر.',
  'Donation assistant' => 'مساعد التبرع',
  'Off.' => 'إيقاف.',
  'AI key or model is missing.' => 'مفتاح الذكاء الاصطناعي أو النموذج مفقود.',
  'On but not replying: ' => 'قيد التشغيل ولكن لا يرد:',
  'On. Donation types offered: %s.' => 'على. أنواع التبرعات المقدمة: %s.',
  '%s does not support tools; choose a tool-capable model for the assistant.' => '%s لا يدعم الأدوات؛ اختر نموذجًا قادرًا على استخدام الأدوات للمساعد.',
  'Receipt reading model' => 'نموذج قراءة الإيصال',
  '%s cannot read images; the receipt pre-check will not work. Choose an image-capable receipt reading model.' => 'لا يستطيع %s قراءة الصور؛ لن يعمل الفحص المسبق للاستلام. اختر نموذجًا لقراءة الإيصالات مزودًا بالصور.',
  'Assistant payment details' => 'تفاصيل الدفع للمساعد',
  'Recipient name and IBAN set.' => 'اسم المستلم ومجموعة IBAN.',
  'Recipient name or IBAN missing; bank details cannot be sent after confirmation.' => 'اسم المستلم أو رقم IBAN مفقود؛ لا يمكن إرسال التفاصيل المصرفية بعد التأكيد.',
  'Donation page link' => 'رابط صفحة التبرع',
  'Donation page not found; the assistant will not send a link.' => 'لم يتم العثور على صفحة التبرع؛ لن يرسل المساعد رابطًا.',
  'Background requests' => 'طلبات الخلفية',
  'The site could not send a background request to itself (%1$s: %2$s). Queued replies and the benchmark may move slowly; a security plugin or the server firewall may be blocking /wp-json/flx-chat/ requests.' => 'تعذر على الموقع إرسال طلب خلفية إلى نفسه (%1$s: %2$s). الردود الموجودة في قائمة الانتظار وقد يتحرك المؤشر ببطء؛ قد يقوم مكون إضافي للأمان أو جدار حماية الخادم بحظر طلبات /wp-json/flx-chat/.',
  'error' => 'خطأ',
  'warning' => 'تحذير',
  'ok' => 'حسنا',
  'Your {marka} verification code: {kod}' => 'رمز التحقق {marka} الخاص بك: {kod}',
  'The code is valid for {dk} minutes. Type it in your WhatsApp chat with us. If you did not ask for it, ignore this message.' => 'الرمز صالح لمدة {dk} دقيقة. اكتبه في دردشة الواتساب الخاصة بك معنا. إذا لم تطلب ذلك، تجاهل هذه الرسالة.',
  'Something went wrong; our team will contact you as soon as possible 🌱 Meanwhile, feel free to ask anything else.' => 'حدث خطأ ما؛ سيقوم فريقنا بالتواصل معك في أقرب وقت ممكن 🌱 وفي الوقت نفسه، لا تتردد في سؤال أي شيء آخر.',
  'Verification attempt failed (%1$d/%2$d): %3$s' => 'فشلت محاولة التحقق (%1$d/%2$d): %3$s',
  'The person wanted to see their records but could not be verified; someone from the team should get in touch' => 'أراد الشخص رؤية سجلاته ولكن لم يتمكن من التحقق منها؛ يجب أن يتصل بك أحد أعضاء الفريق',
  'e-mail could not be sent (check Flux Mail › SMTP settings)' => 'تعذر إرسال البريد الإلكتروني (تحقق من Flux Mail › إعدادات SMTP)',
  'The assistant sent a verification code for %1$s (%2$s).' => 'أرسل المساعد رمز التحقق لـ%1$s(%2$s).',
  'code expired' => 'انتهت صلاحية الرمز',
  'wrong code' => 'رمز خاطئ',
  'The person verified the code for %s; it is added to their record lookups.' => 'قام الشخص بالتحقق من رمز %s؛ تتم إضافته إلى عمليات البحث عن السجلات الخاصة بهم.',
  'Claude models cannot read audio; choose an audio-capable OpenRouter model in Settings › AI › Voice message model.' => 'لا تستطيع نماذج كلود قراءة الصوت؛ اختر طراز OpenRouter مزودًا بإمكانيات الصوت في الإعدادات › AI › نموذج الرسالة الصوتية.',
  'The audio could not be transcribed.' => 'لا يمكن نسخ الصوت.',
  'The audio file could not be read.' => 'لا يمكن قراءة الملف الصوتي.',
  'Voice message (%1$s) transcribed: %2$s' => 'الرسالة الصوتية (%1$s) مكتوبة: %2$s',
  'Voice message (%1$s) could not be processed: %2$s' => 'لا يمكن معالجة الرسالة الصوتية (%1$s): %2$s',
  'This action is not available on an official WhatsApp Cloud API line.' => 'هذا الإجراء غير متاح على خط WhatsApp Cloud API الرسمي.',
  'WhatsApp 24-hour rule: the contact has not written in the last 24 hours, so the Cloud API will not send a free-form message; only an approved template can be sent. Try again once they write.' => 'قاعدة WhatsApp على مدار 24 ساعة: لم تكتب جهة الاتصال خلال الـ 24 ساعة الماضية، لذا لن ترسل Cloud API رسالة ذات شكل حر؛ يمكن إرسال القالب المعتمد فقط. حاول مرة أخرى بمجرد الكتابة.',
  'A Cloud API line needs Flux Mail 1.10.0 or later.' => 'يحتاج خط Cloud API إلى Flux Mail 1.10.0 أو إصدار أحدث.',
  'The Cloud API cannot send to this address (hidden number or group).' => 'لا يمكن لـ Cloud API الإرسال إلى هذا العنوان (رقم أو مجموعة مخفية).',
  'Could not reach the Cloud API account (İletişim › Connections).' => 'تعذر الوصول إلى حساب Cloud API (الاتصالات ›).',
  'A Cloud API line has no QR code; the account is set up in İletişim › Connections.' => 'لا يحتوي خط Cloud API على رمز QR؛ تم إعداد الحساب في Életişim › Connections.',
  'The file could not be prepared.' => 'لا يمكن تحضير الملف.',
  'Flux AI has no image support.' => 'لا يوجد لدى Flux AI دعم للصور.',
  'The image could not be rendered.' => 'لا يمكن تقديم الصورة.',
  'The assistant\'s image could not be sent: ' => 'لا يمكن إرسال صورة المساعد:',
  'Hello {first_name}, we have created your donation record: {donation}, total {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'After paying, you can send the receipt here. Thank you.' => 'مرحبًا {first_name}، لقد أنشأنا سجل التبرع الخاص بك: {donation}، إجمالي {amount}.{bank} بعد الدفع، يمكنك إرسال الإيصال هنا. شكرًا لك.',
  'Hello {first_name}, your donation has been recorded: {donation}, total {amount}.' . chr(10) . '' . chr(10) . 'Thank you for your support.' => 'مرحبًا {first_name}، تم تسجيل تبرعك: {donation}، إجمالي {amount}.' . chr(10) . '' . chr(10) . 'شكرا لدعمكم.',
  'The plugin that would run this scenario is inactive.' => 'البرنامج المساعد الذي سيقوم بتشغيل هذا السيناريو غير نشط.',
  'This user is not allowed to use the staff tools.' => 'لا يسمح لهذا المستخدم باستخدام أدوات الموظفين.',
  '%1$s linked this chat to staff member %2$s' => 'ربطت %1$s هذه الدردشة بالموظف %2$s',
  '%s removed the staff link of this chat' => 'قام %s بإزالة رابط الموظفين الخاص بهذه الدردشة',
  'Chat linked to staff member' => 'الدردشة مرتبطة بالموظف',
  'Staff link removed' => 'تمت إزالة رابط الموظفين',
  '— Not staff —' => '- ليس موظفين -',
  'WhatsApp hides this person\'s number, so the assistant cannot recognise staff by number. If this person is on your team, link them here and the assistant opens the staff tools.' => 'يقوم WhatsApp بإخفاء رقم هذا الشخص، لذلك لا يستطيع المساعد التعرف على الموظفين من خلال الرقم. إذا كان هذا الشخص ضمن فريقك، قم بربطه هنا وسيقوم المساعد بفتح أدوات الموظفين.',
  'The assistant recognises staff by the number in their Flux Roles profile. If the number does not match, you can link them here; in a chat with a known number the number comes first.' => 'يتعرف المساعد على الموظفين من خلال الرقم الموجود في ملف تعريف Flux الأدوار الخاص بهم. إذا كان الرقم غير متطابق، يمكنك ربطهم هنا؛ في الدردشة مع رقم معروف يأتي الرقم أولا.',
  'This channel is not available right now.' => 'هذه القناة غير متوفرة حاليا.',
  'Site chat' => 'دردشة الموقع',
  'All messages from WhatsApp, site chat and other channels appear here live. Pick a chat on the left.' => 'جميع الرسائل من الواتساب ودردشة الموقع والقنوات الأخرى تظهر هنا مباشرة. اختر الدردشة على اليسار.',
  '[[\'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.\', \'tr\']]' => 'مركز اتصال WhatsApp (Evolution API): شاهد الرسائل الواردة والصادرة المباشرة، وابدأ محادثة جديدة، والردود الجاهزة، والعلامات، والمهمة، والملاحظات الداخلية، والردود التلقائية؛ التبرع (Flux Donate) وتسجيل الشهادة (Flux الشهادات) من الدردشة، ومطابقة الاستلام. اقتراح استجابة الذكاء الاصطناعي ومساعد التبرع التلقائي مع OpenRouter.',
  'Çağrı Merkezi' => 'مركز الاتصال',
  'Sohbetler' => 'الدردشات',
  'AI asistan' => 'مساعد الذكاء الاصطناعي',
  'Çağrı Merkezi Ayarları' => 'إعدادات مركز الاتصال',
  'Ayarlar' => 'الإعدادات',
  'Çağrı Merkezi için JavaScript gerekli.' => 'مطلوب جافا سكريبت لمركز الاتصال.',
  'Bu sayfaya erişim yetkiniz yok.' => 'ليس لديك إذن للوصول إلى هذه الصفحة.',
  'Asistanın yazıştığı sohbetleri izleyin, talimatını ve belgelerini düzenleyin, değişiklikleri yayına almadan önce test edin.' => 'مراقبة الدردشات التي يتعامل معها المساعد، وتحرير تعليماتها ومستنداتها، واختبار التغييرات قبل نشرها.',
  'Asistan ayarları' => 'إعدادات المساعد',
  'Bu sayfa için JavaScript gerekli.' => 'هذه الصفحة تتطلب جافا سكريبت.',
  'Kapalı' => 'مغلق',
  'Açık, 5 dakika' => 'على، 5 دقائق',
  'Açık, 1 saat' => 'على، 1 ساعة',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli; kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a anahtarı girin.' => 'يحتاج الذكاء الاصطناعي إلى البرنامج المساعد Flux AI & MCP؛ قم بتثبيته وتنشيطه، ثم أدخل المفتاح في Flux AI & MCP ›الإعدادات.',
  'Yapay zekâ modeli seçilmemiş.' => 'لم يتم تحديد نموذج الذكاء الاصطناعي.',
  'Flux AI\'de Anthropic (Claude) anahtarı girilmemiş.' => 'لم يتم إدخال أي مفتاح Anthropic (Claude) في Flux AI.',
  'Flux AI\'de OpenRouter anahtarı girilmemiş.' => 'لم يتم إدخال أي مفتاح OpenRouter في Flux AI.',
  'Model listesi için Flux AI & MCP eklentisi gerekli.' => 'تحتاج قائمة النماذج إلى البرنامج المساعد Flux AI & MCP.',
  'Flux Chat: yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin; Çağrı Merkezi\'nde kayıtlı anahtarlar oraya kendiliğinden aktarılır.' => 'مركز اتصال Flux: تحتاج ميزات الذكاء الاصطناعي (الاقتراحات والمساعد وقراءة الإيصالات والرسائل الصوتية والملخصات) إلى البرنامج الإضافي Flux AI & MCP. تثبيته وتفعيله؛ يتم نقل المفاتيح المحفوظة في مركز الاتصال هناك تلقائيًا.',
  'Flux Chat: %s anahtarı Flux AI\'de farklı bir anahtar olarak zaten kayıtlı; Flux AI\'deki kullanılıyor. Çağrı Merkezi\'ndeki eski anahtar aktarılmadı ve artık kullanılmıyor.' => 'مركز اتصال Flux: تم بالفعل حفظ مفتاح %s مختلف في Flux AI وهو المفتاح المستخدم. لم يتم نقل مفتاح مركز الاتصال القديم ولم يعد مستخدمًا.',
  'Flux Chat: yapay zekâ anahtarları Flux AI\'ye aktarıldı. Bundan sonra anahtar, harcama sınırı ve kayıtlar Flux AI\'den yönetilir; model seçimleri Çağrı Merkezi\'nde kalır.' => 'مركز اتصال Flux: تم نقل مفاتيح الذكاء الاصطناعي إلى Flux AI. من الآن فصاعدًا، تتم إدارة المفاتيح وحدود الإنفاق والسجلات في Flux AI؛ تبقى خيارات النماذج في مركز الاتصال.',
  'Flux Donate eklentisi etkin değil; asistan bağış türlerini ve fiyatları oradan alır.' => 'البرنامج المساعد Flux Donate غير نشط؛ يقوم المساعد بأخذ أنواع التبرعات وأسعارها منها.',
  'Flux Donate\'ta açık bağış türü yok (Bağış türleri sayfasından bir türü açın).' => 'لا يوجد نوع تبرع مفتوح في Flux Donate (افتح نوعًا في صفحة أنواع التبرعات).',
  'Asistan için seçilen bağış türleri kapalı ya da fiyatsız; açık bir tür seçin ya da seçimi boş bırakın.' => 'أنواع التبرعات المختارة للمساعد مغلقة أو ليس لها ثمن؛ حدد نوعًا مفتوحًا أو اترك التحديد فارغًا.',
  'Açık bağış türlerinin hiçbirinde fiyat yok (Flux Donate › Bağış türleri › seçenek fiyatı).' => 'لا يوجد سعر لأي من أنواع التبرعات المفتوحة (Flux Donate › أنواع التبرع › سعر الخيار).',
