  'Dekontunuzu aldık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'لقد استلمنا إيصالك، شكرًا لك 🌱 سنرد عليك بخصوص دفعتك في أقرب وقت ممكن.',
  'Dekontunuzu aldık, teşekkür ederiz 🌱 Bağışınız onaylandı.' => 'لقد استلمنا إيصالك، شكرًا لك 🌱 تم تأكيد تبرعك.',
  'Bu dekontu daha önce almıştık, teşekkür ederiz 🌱 Ödemenizle ilgili size en kısa zamanda dönüş yapacağız.' => 'لقد تلقينا هذا الإيصال بالفعل، شكرًا لك 🌱 سنرد عليك بشأن دفعتك في أقرب وقت ممكن.',
  'Bu dekont daha önce sistemimize yüklenmiş görünüyor. Aynı dekont ikinci bir bağış için kullanılamaz. Farklı bir ödeme yaptıysanız o ödemenin dekontunu gönderebilirsiniz; ekibimiz de ayrıca kontrol edecek.' => 'يبدو أن هذا الإيصال قد تم تحميله إلى نظامنا من قبل. لا يمكن استخدام نفس الإيصال للتبرع الثاني. إذا قمت بإجراء دفعة مختلفة، يرجى إرسال هذا الإيصال؛ سيقوم فريقنا أيضًا بالتحقق.',
  'Dekontunuzu aldık. Dekonttaki tutar (%1$s) bağışınızın tutarıyla (%2$s) uyuşmuyor gibi görünüyor. Kontrol edebilir misiniz? Farklı bir ödeme yaptıysanız buradan yazabilirsiniz, ekibimiz de ayrıca bakacak.' => 'لقد تلقينا إيصالك. يبدو أن المبلغ الموجود عليه (%1$s) لا يتطابق مع مبلغ تبرعك (%2$s). هل يمكنك التحقق من ذلك؟ إذا قمت بإجراء دفعة مختلفة، يمكنك الكتابة هنا؛ سوف يقوم فريقنا أيضًا بإلقاء نظرة.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı derneğimiz değil gibi görünüyor. Bağışlarımız yalnız "%s" adına açılmış hesabımıza yapılır. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'لقد استلمنا إيصالك، ولكن لا يبدو أن المستلم هو مؤسستنا. التبرعات تتم فقط لحسابنا بإسم "%s". هل يمكنك التحقق؟ سوف يقوم فريقنا أيضًا بإلقاء نظرة.',
  'Dekontunuzu aldık, ancak dekonttaki alıcı bilgisi bizim hesabımızla eşleşmiyor gibi görünüyor. Kontrol edebilir misiniz? Ekibimiz de ayrıca bakacak.' => 'لقد تلقينا إيصالك، ولكن يبدو أن المستلم الموجود عليه لا يتطابق مع حسابنا. هل يمكنك التحقق؟ سوف يقوم فريقنا أيضًا بإلقاء نظرة.',
  'Gönderdiğiniz dosya bir ödeme dekontuna benzemiyor. Ödemeyi yaptıysanız dekontu ya da ödeme ekranının görüntüsünü buradan gönderebilirsiniz.' => 'الملف الذي أرسلته لا يبدو كإيصال الدفع. إذا قمت بالدفع، يمكنك إرسال الإيصال أو لقطة شاشة لشاشة الدفع هنا.',
