  'Alıcının numarası Kullanıcılar › Profil › WhatsApp numarası alanından gelir; yetkiler Kullanıcılar › Roller ve erişim sayfasından (rapor alabilir, genel raporu görebilir, raporları yönetir). Rapor seçilen saatte gider; sunucu zamanlayıcısı yoksa sitenin ilk ziyaretinde ya da sohbet panelinde gönderilir.' => 'يأتي رقم المستلم من المستخدمين › الملف الشخصي › رقم WhatsApp؛ الأذونات من المستخدمين › الأدوار والوصول (تلقي التقارير وعرض التقرير الشامل وإدارة التقارير). التقارير تخرج في الوقت المختار؛ بدون جدولة الخادم، يتم إرسالها عند زيارة الموقع التالية أو استخدام لوحة الدردشة.',
