  'Bu kişi kara listede; mesaj gönderilmez. Kara listeden çıkarınca yeniden yazabilirsiniz.' => 'تم إدراج جهة الاتصال هذه في القائمة المحظورة؛ يتم إرسال أية رسائل. قم بإزالتهم من قائمة الحظر للكتابة مرة أخرى.',
  'Mesaj kaydedilemedi.' => 'لا يمكن حفظ الرسالة.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API (sürüm %s) bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'تكتب جهة الاتصال هذه من رقم WhatsApp مخفي (@lid) ولا يمكن إرسال Evolution API (الإصدار %s) إلى هذا العنوان. قم بتحديث خادم Evolution API إلى الإصدار 2.3 أو الأحدث؛ إذا وصل الرقم الحقيقي لجهة الاتصال، يرسل البرنامج المساعد هناك.',
  'Bu kişi WhatsApp gizli numarasıyla (@lid) yazıyor ve Evolution API bu adrese gönderemedi. Evolution API sunucusunu 2.3 veya üstüne güncelleyin; kişinin gerçek numarası gelirse eklenti oraya gönderir.' => 'تكتب جهة الاتصال هذه من رقم WhatsApp مخفي (@lid) ولا يمكن لـ Evolution API الإرسال إلى هذا العنوان. قم بتحديث خادم Evolution API إلى الإصدار 2.3 أو الأحدث؛ إذا وصل الرقم الحقيقي لجهة الاتصال، يرسل البرنامج المساعد هناك.',
