  'Bağlı ✓' => 'متصل ✓',
  'Bağlı değil (durum: %s). QR ile bağlayın.' => 'غير متصل (الحالة: %s). تواصل مع QR.',
  'Webhook bu siteye ayarlı ✓' => 'يشير Webhook إلى هذا الموقع ✓',
