  '(eski: gizli numaralı (@lid) kişilere cevap gidemeyebilir, 2.3 veya üstüne güncelleyin)' => '(قديم: قد تفشل الردود على جهات الاتصال ذات الرقم المخفي (@lid)، قم بالتحديث إلى الإصدار 2.3 أو الأحدث)',
  'Webhook bu siteye ayarlı değil. "Webhook\'u kur" düğmesine basın.' => 'لم يتم توجيه خطاف الويب إلى هذا الموقع. اضغط على "إعداد خطاف الويب".',
  'Webhook kuruldu ✓ Artık gelen mesajlar buraya düşer.' => 'تم إعداد Webhook ✓ ستصل الرسائل الواردة هنا الآن.',
  'Son sohbetler içe aktarılıyor, bu biraz sürebilir…' => 'جارٍ استيراد الدردشات الأخيرة، قد يستغرق ذلك بعض الوقت...',
  'Evolution\'da kayıtlı mesaj: %s' => 'الرسائل المخزنة في Evolution: %s',
  'Evolution mesajları kaydetmiyor, bu yüzden eski mesajlar gelemez. Evolution sunucusunda DATABASE_SAVE_DATA_NEW_MESSAGE ve DATABASE_SAVE_DATA_HISTORIC değerlerini true yapın; eski konuşmalar için hattı QR ile yeniden bağlarken instance ayarında "Sync full history" açık olsun.' => 'لا يقوم Evolution بتخزين الرسائل، لذا لا يمكن تحميل الرسائل الأقدم. على خادم Evolution، قم بتعيين DATABASE_SAVE_DATA_NEW_MESSAGE وDATABASE_SAVE_DATA_HISTORIC على true؛ بالنسبة للمحادثات القديمة، احتفظ بميزة "مزامنة السجل الكامل" في إعدادات المثيل عند إعادة توصيل الخط باستخدام QR.',
  '%1$s sohbet, %2$s mesaj içe aktarıldı ✓' => 'دردشات %1$s، استيراد رسائل %2$s✓',
