  'Ayarlar kaydedildi.' => 'تم حفظ الإعدادات.',
  'Çağrı Merkezi\'nin çalışması için gereken bağlantılar ve ayarlar. Kayıtlı durumlar gösterilir; canlı deneme için ilgili sekmedeki "test et" düğmelerini kullanın. Aynı kontroller temanın sistem kontrolü ekranında diğer eklentilerle birlikte de görünür.' => 'الاتصالات والإعدادات التي يحتاجها مركز الاتصال. تظهر الحالة المحفوظة. استخدم أزرار "الاختبار" في كل علامة تبويب لإجراء فحص مباشر. تظهر نفس عمليات التحقق أيضًا مع المكونات الإضافية الأخرى على شاشة فحص النظام الخاصة بالقالب.',
  'WhatsApp hatları' => 'خطوط واتس اب',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. WhatsApp bağlantıları Flux Mail\'de yönetilir; burada hangisinin kullanılacağını seçin. Adres ve API key orada kalır, değişince burada ayrıca güncellemek gerekmez.' => 'يتم إرسال الرسائل واستلامها من خلال Evolution API. تتم إدارة اتصالات WhatsApp في Flux Mail؛ اختر أي واحد لاستخدامه هنا. يظل عنوان URL ومفتاح واجهة برمجة التطبيقات هناك، لذا لا تحتاج إلى تحديثهما هنا عند تغييرهما.',
  'İletişim › Bağlantılar' => 'الاتصالات › اتصالات',
  'Mesajlar Evolution API üzerinden gönderilir ve alınır. Flux Certificates eklentisinde Evolution sağlayıcısı tanımlıysa aynı bağlantıyı seçebilirsiniz; adres ve API key orada kalır.' => 'يتم إرسال الرسائل واستلامها عبر Evolution API. إذا تم إعداد موفر التطور في شهادات Flux، فيمكنك اختيار نفس الاتصال؛ يبقى عنوان URL ومفتاح واجهة برمجة التطبيقات هناك.',
  'Hat ekle' => 'إضافة خط',
