  '"Webhook\'u kur" düğmesine basın. Gelen mesajlar, telefondan ve Flux Certificates\'dan gönderilenler canlı olarak buraya düşer.' => 'اضغط على "إعداد خطاف الويب". تظهر الرسائل الواردة والرسائل المرسلة من الهاتف ومن شهادات Flux هنا مباشرة.',
