  'Etiket ekle' => 'إضافة تسمية',
  'Etiket adı' => 'اسم التسمية',
  'Sohbetten kayıt oluşturma' => 'إنشاء سجلات من الدردشات',
  'Sohbet başlığındaki düğmelerle bağış kaydı (Flux Donate) ve sertifika (Flux Certificates) oluşturulur, gelen dekont kayıtla eşleştirilir. Eklenti kurulu değilse ilgili düğme görünmez.' => 'تقوم الأزرار الموجودة في رأس الدردشة بإنشاء سجل تبرع (Flux Donate) وشهادة (Flux Certifieds)، وتتم مطابقة الإيصال الوارد مع السجل. إذا لم يتم تثبيت البرنامج الإضافي، فسيتم إخفاء الزر الخاص به.',
  'Temsilciler bağış kaydı oluşturabilsin ve dekont eşleştirebilsin' => 'يمكن للوكلاء إنشاء سجلات التبرعات ومطابقة الإيصالات',
  'Temsilciler sertifika oluşturup gönderebilsin' => 'يمكن للوكلاء إنشاء وإرسال الشهادات',
  'Mesaj kutusunun üstünde hazır cevap baloncuklarını göster' => 'إظهار فقاعات الرد السريع أعلى مربع الرسالة',
  'Bağış mesajları' => 'رسائل التبرع',
  'Kayıt oluşturulunca kişiye gönderilecek hazır metinler (gönderimden önce düzenlenebilir). Boş bırakılırsa varsayılan metin kullanılır.' => 'النصوص الجاهزة تُرسل إلى الشخص عند إنشاء سجل (قابلة للتحرير قبل الإرسال). إذا تركت فارغة، يتم استخدام النص الافتراضي.',
  'Ödeme bekleniyor (havale sözü)' => 'في انتظار الدفع (التحويل الموعود)',
  'Bağış alındı' => 'تم استلام التبرع',
  'Dekont onaylandı' => 'تم تأكيد الاستلام',
  'Banka bilgisi ({bank})' => 'تفاصيل البنك ({bank})',
  'Alıcı adı, banka, IBAN' => 'اسم المستلم، البنك، رقم IBAN',
  'Boşsa WooCommerce › Ödemeler › Havale / EFT ayarındaki hesap kullanılır.' => 'إذا كان فارغًا، فسيتم استخدام الحساب في WooCommerce › المدفوعات › التحويل البنكي.',
  'Değişkenler: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.' => 'المتغيرات: {first_name}, {name}, {donation}, {amount}, {quantity}, {bank}, {certificate_link}, {agent}, {brand}, {date}.',
  'Yapay zekâ bağlantısı' => 'اتصال الذكاء الاصطناعي',
  'Anahtarlar, prompt önbelleği, harcama sınırı ve kullanım kayıtları Flux AI & MCP eklentisinden gelir; Çağrı Merkezi\'nin tüm yapay zekâ istekleri oradan geçer. Model seçimleri burada kalır; alanlar boşsa Flux AI\'de bu eklentiye seçilen model (ya da varsayılan) kullanılır.' => 'تأتي المفاتيح والتخزين المؤقت السريع وحدود الإنفاق وسجلات الاستخدام من البرنامج الإضافي Flux AI & MCP؛ تمر جميع طلبات الذكاء الاصطناعي الخاصة بمركز الاتصال من خلاله. تبقى خيارات النماذج هنا؛ إذا كان الحقل فارغًا، فسيتم استخدام النموذج المختار لهذا البرنامج المساعد في Flux AI (أو الافتراضي).',
  'Flux AI ayarlarını aç' => 'افتح إعدادات Flux AI',
  'Yapay zekâ için Flux AI & MCP eklentisi gerekli. Kurup etkinleştirin ve Flux AI & MCP › Ayarlar\'a OpenRouter ve/veya Anthropic anahtarını girin. O zamana kadar öneri, asistan, dekont okuma, sesli mesaj ve özet kapalıdır.' => 'يحتاج الذكاء الاصطناعي إلى البرنامج المساعد Flux AI & MCP. قم بتثبيته وتنشيطه، ثم أدخل مفتاح OpenRouter و/أو Anthropic في إعدادات Flux AI & MCP. حتى ذلك الحين، يتم إيقاف الاقتراحات والمساعد وقراءة الإيصالات والرسائل الصوتية والملخصات.',
  'Yaratıcılık (0–1)' => 'الإبداع (0-1)',
  'Düşük değer daha tutarlı, yüksek değer daha serbest cevap verir. Önerilen 0,4.' => 'تعطي القيم المنخفضة ردودًا أكثر اتساقًا، بينما توفر القيم الأعلى إجابات أكثر حرية. 0.4 الموصى بها.',
  'Model (öneriler için)' => 'النموذج (للإقتراحات)',
  'Asistan modeli (isteğe bağlı)' => 'نموذج مساعد (اختياري)',
  'Yukarıdaki model' => 'النموذج أعلاه',
  'Yalnız araç (tools) destekleyen modeller listelenir.' => 'يتم سرد النماذج التي تدعم الأدوات فقط.',
  'Dekont okuma modeli (isteğe bağlı)' => 'نموذج قراءة الإيصال (اختياري)',
  'Seçilen model görsel okuyamıyorsa görsel okuyan ucuz bir modele kendiliğinden geçilir.' => 'إذا لم يتمكن النموذج المحدد من قراءة الصور، فسيتم استخدام نموذج رؤية رخيص تلقائيًا.',
  'Bu ay (%1$s): %2$s istek, %3$s token, yaklaşık $%4$s.' => 'هذا الشهر (%1$s): طلبات %2$s، رموز %3$s، حوالي %4$s دولار.',
  'Cevap önerisi' => 'الرد على الاقتراحات',
  'Mesaj kutusunun üstünde, konuşmaya göre sıradaki mesaj önerilir. Temsilci "Gönder" der ya da "Düzenle" ile kutuya alıp değiştirir. Öneri asla kendiliğinden gönderilmez.' => 'أعلى مربع الرسالة، يتم اقتراح الرسالة التالية من المحادثة. ينقر الوكيل على "إرسال" أو يأخذه إلى المربع باستخدام "تحرير". لا يتم إرسال الاقتراح من تلقاء نفسه أبدًا.',
  'Son mesaj kişiden geldiyse öneri kendiliğinden hazırlansın (kapalıysa ✨ düğmesiyle istenir)' => 'قم بإعداد اقتراح تلقائيًا عند وصول آخر رسالة من الشخص (إذا كان متوقفًا، اسأل باستخدام الزر ✨)',
  'Kurum bilgisi ve üslup' => 'معلومات المنظمة والنبرة',
  'Ör. Derneğimiz İstanbul\'da fidan dikimi yapar. Dikimler her yıl Kasım–Mart arasında yapılır. Sertifika bağıştan sonra WhatsApp\'tan gönderilir. Samimi ama resmi bir dil kullan.' => 'على سبيل المثال جمعيتنا تزرع شتلات في اسطنبول. تتم الزراعة كل عام بين نوفمبر ومارس. يتم إرسال الشهادة على الواتساب بعد التبرع. استخدم لهجة دافئة ولكن رسمية.',
  'Öneri ve asistan bu bilgileri kullanır. Bağış türleri, fiyatlar, banka bilgisi ve hazır cevaplar ayrıca otomatik eklenir.' => 'الاقتراحات والمساعد يستخدم هذا. تتم إضافة أنواع التبرعات والأسعار والتفاصيل المصرفية والردود السريعة تلقائيًا.',
  'Öneri sağlayıcısı' => 'مزود الاقتراح',
  'Bağış asistanı (otomatik cevap)' => 'مساعد التبرعات (الردود التلقائية)',
  'Açıkken asistan gelen mesajlara kendisi cevap verir: karşılar, hitap için adını sorar, bağış seçeneklerini ve fiyatları gönderir, isteğe bağlı e-posta ve "kimin adına" bilgilerini alır, her değişiklikte özet gösterip onay ister. Onaydan sonra Flux Donate\'ta "ödeme bekleniyor" kaydı açar ve bağış linki ile alıcı adı, IBAN, açıklamayı ayrı mesajlar hâlinde gönderir. Konu bağış dışına çıkarsa sohbeti ekibe devreder.' => 'عند التشغيل، يقوم المساعد بالرد على نفسه: يرحب، ويطلب الاسم لمخاطبتهم، ويرسل خيارات التبرع والأسعار، ويجمع بشكل اختياري البريد الإلكتروني و"باسم من"، ويطلب التأكيد بعد كل تغيير. بعد التأكيد، يفتح سجل "في انتظار الدفع" في Flux Donate ويرسل رابط التبرع والمستلم ورقم IBAN والمرجع كرسائل منفصلة. إذا ترك الموضوع تبرعات، فسيتم تسليم الدردشة إلى الفريق.',
  'Flux Donate eklentisi etkin değil; asistan bağış kaydı açamaz.' => 'البرنامج المساعد Flux Donate غير نشط؛ لا يمكن للمساعد إنشاء سجلات التبرع.',
  'Talimat, belgeler, AI sohbetleri ve test sohbeti' => 'التعليمات والمستندات ومحادثات الذكاء الاصطناعي والدردشة التجريبية',
  'Bağış asistanını aç (tümünü kapatmak için işareti kaldırın)' => 'قم بتشغيل مساعد التبرعات (قم بإزالة التحديد لإيقاف تشغيله في كل مكان)',
  'Hangi sohbetlerde cevap versin' => 'ما هي الدردشات التي يجب الرد عليها؟',
  'Tüm sohbetlerde (önerilen)' => 'في جميع الدردشات (مستحسن)',
  'Temsilciye atanmamış sohbetlerde' => 'في الدردشات التي لم يتم تعيينها لوكيل',
  'Yalnız mesai saatleri dışında' => 'فقط خارج أوقات العمل',
  'Bir temsilci sohbete yazdığında (panelden ya da telefondan) asistan o sohbette aşağıdaki süre kadar susar. Sohbet başlığındaki asistan düğmesiyle sohbet bazında açılıp kapatılır.' => 'عندما يكتب أحد الوكلاء في محادثة (من اللوحة أو الهاتف)، يظل المساعد هادئًا هناك طوال الوقت أدناه. استخدم زر المساعد الموجود في رأس الدردشة لتشغيله أو إيقاف تشغيله لكل دردشة.',
  'Test modu: yalnız aşağıdaki numaralarda cevap ver' => 'وضع الاختبار: الرد فقط على الأرقام أدناه',
  'Test numaraları' => 'أرقام الاختبار',
  'Virgül ya da satır ile ayırın. Test modu kapalıyken kullanılmaz.' => 'افصل بفواصل أو أسطر جديدة. لا يُستخدم عند إيقاف تشغيل وضع الاختبار.',
  'Temsilci yazınca susma (saat)' => 'هادئ بعد أن يكتب الوكيل (ساعات)',
  'Fiyat listesindeki adetler' => 'الكميات في قائمة الأسعار',
  'Konuşma geçmişi (saat)' => 'سجل المحادثات (ساعات)',
  'Asistan cevaptan önce bu süredeki tüm mesajları okur.' => 'قبل الرد، يقرأ المساعد جميع الرسائل من هذه الفترة.',
  'Asistanın sunduğu bağış türleri' => 'أنواع التبرعات التي يقدمها المساعد',
  'Hiçbiri seçilmezse açık olan tüm türler sunulur. Yeni tür Flux Donate\'ta açıldığında asistan onu da bilir.' => 'إذا لم يتم تحديد أي شيء، فسيتم عرض كافة الأنواع المفتوحة. عند فتح نوع جديد في Flux Donate، يعرف المساعد ذلك أيضًا.',
  'Dekont ön kontrolü: kişi dekont gönderince yapay zekâ tutarı, alıcıyı ve IBAN\'ı bağışla karşılaştırır, sonucu kişiye söyler, dosyayı bağış kaydına ekler ve son onay için sohbeti ekibe devreder (ödendi işaretlemez)' => 'التحقق المسبق من الاستلام: عندما ترسل جهة الاتصال إيصالاً، يقارن الذكاء الاصطناعي المبلغ والمستلم ورقم الحساب المصرفي الدولي مع التبرع، ويخبر جهة الاتصال بالنتيجة، ويرفق الملف بسجل التبرع ويسلم الدردشة إلى الفريق للحصول على الموافقة النهائية (لا يتم وضع علامة على أنها مدفوعة)',
  'Fiyat listesinin son satırı' => 'السطر الأخير من قائمة الأسعار',
  'Ödeme bilgileri' => 'تفاصيل الدفع',
  'Alıcı adı ve IBAN boşsa WooCommerce › Ödemeler › Havale / EFT ayarındakiler kullanılır (siparişlerde görünen hesap). Yalnız asistan için farklı hesap istiyorsanız doldurun.' => 'إذا كان المستلم ورقم IBAN فارغين، فسيتم استخدام تلك الموجودة في WooCommerce › المدفوعات › التحويل البنكي (الحساب الموضح في الطلبات). املأها فقط إذا كان على المساعد استخدام حساب مختلف.',
  'Alıcı adı' => 'اسم المستلم',
  'Havale açıklaması' => 'وصف النقل',
  'Değişkenler: {type}, {name}, {amount}, {quantity}' => 'المتغيرات: {type}، {name}، {amount}، {quantity}',
  'Bağış sayfası adresi' => 'عنوان URL لصفحة التبرع',
  'Linke seçilen tür ve adet eklenir (?flxb_opt=…&flxb_qty=…).' => 'يتم إضافة النوع والكمية المحددة إلى الرابط (?flxb_opt=...&flxb_qty=...).',
  'Ödeme bilgilerinden sonraki mesaj' => 'رسالة بعد تفاصيل الدفع',
  'Bağış iptali onay sorusu' => 'سؤال إلغاء التبرع',
  'Asistan yalnız ödenmemiş bağışları, kişinin onayıyla iptal eder. Boşsa varsayılan metin. Değişkenler: {bagis}, {tutar}.' => 'يقوم المساعد بإلغاء التبرعات غير المدفوعة فقط، مع تأكيد الشخص. فارغ = النص الافتراضي. المتغيرات: {bagis}، {tutar}.',
  'Günlük sınır dolunca gönderilen mesaj' => 'يتم إرسال الرسالة عند الوصول إلى الحد اليومي',
  'Sohbet o günkü cevap sınırına ulaşınca bir kez gider, sohbet ekibe devredilir. Sınır sohbetin ⋮ menüsü › Asistan kullanımı ekranından sıfırlanır.' => 'يتم إرساله مرة واحدة عندما تصل الدردشة إلى حد الرد اليومي؛ يتم تسليم الدردشة إلى الفريق. أعد ضبطه من قائمة الدردشة ⋮ › استخدام المساعد.',
  'Ekibe devrederken gönderilen mesaj' => 'تم إرسال الرسالة عند التسليم للفريق',
  'Asistan cevap veremezse giden mesaj' => 'يتم إرسال الرسالة عندما لا يتمكن المساعد من الرد',
  'Yapay zekâ hata verir, süre aşılır ya da yoğunlukta sıra çok uzarsa kişiye bu mesaj gider ve sohbet ekibe devredilir; kişi hiçbir durumda cevapsız kalmaz.' => 'إذا فشل الذكاء الاصطناعي، أو تم الوصول إلى الحد الزمني أو أصبحت قائمة الانتظار طويلة جدًا، فسيتم إرسال هذه الرسالة وتسليم الدردشة إلى الفريق؛ لا يترك الشخص أبدًا بدون إجابة.',
  'Bekleme mesajından önce en az (sn)' => 'الحد الأدنى للانتظار قبل الرسالة (الرسائل) المعلقة',
  'Kişinin mesajından bu kadar saniye geçmeden bekleme mesajı gitmez; bu arada asistan yeniden dener.' => 'لا يتم إرسال الرسالة المعلقة إلا بعد عدة ثوانٍ من رسالة الشخص؛ وفي الوقت نفسه يقوم المساعد بإعادة المحاولة.',
  'Bir cevabın en uzun süresi (sn)' => 'أطول وقت لإجابة واحدة (إجابات)',
  'Hostinger istekleri ~60 sn\'de kesebilir; 50 önerilir.' => 'يمكن لـ Hostinger قطع الطلبات في حوالي 60 ثانية؛ يوصى بـ 50.',
  'Devirde bildirim gidecek numaralar' => 'تم إخطار الأرقام عند التسليم',
  'Asistan bir sohbeti ekibe devredince bu numaralara aynı hattan WhatsApp mesajı gider: kişinin adı, telefonu, nedeni, son mesajları ve panel linki. Virgül ya da satır ile ayırın. Bu numaralarla asistan konuşmaz.' => 'عندما يقوم المساعد بتسليم الدردشة إلى الفريق، يتم إرسال رسالة WhatsApp إلى هذه الأرقام من نفس السطر: اسم جهة الاتصال والهاتف والسبب والرسائل الأخيرة ورابط اللوحة. افصل بفواصل أو أسطر جديدة. المساعد لا يتحدث مع هذه الأرقام.',
  'Kişi bunlardan birini yazınca asistan beklemeden yukarıdaki devir mesajını gönderir ve o sohbette kapanır. Boş bırakılırsa örnekteki liste kullanılır.' => 'عندما تكتب جهة الاتصال إحدى هذه الرسائل، يرسل المساعد على الفور رسالة التسليم أعلاه ويتم إيقاف تشغيله في تلك الدردشة. إذا تركت فارغة، يتم استخدام قائمة الأمثلة.',
  'Asistana ek talimatlar' => 'تعليمات اضافية للمساعد',
  'Ör. Fidanların dikileceği yer: Kocaeli. Sertifikalar bağış onaylanınca gönderilir.' => 'على سبيل المثال يتم زرع الشتلات في قوجه ايلي. يتم إرسال الشهادات بمجرد تأكيد التبرع.',
  'Kişi mesaj istemeyince gönderilen son mesaj' => 'الرسالة الأخيرة عندما تقوم جهة اتصال بإلغاء الاشتراك',
  'Kişi "bana mesaj atmayın" gibi bir şey yazınca asistan bu mesajı gönderir ve kişiyi kara listeye alır. Kara listedeki kişiye WhatsApp, e-posta ve SMS gitmez; listeyi Sohbetler › ☰ › Kara liste\'den yönetirsiniz.' => 'إذا كتب شخص ما شيئًا مثل "لا تراسلني"، فسيرسل المساعد هذه الرسالة ويضعه في قائمة الحظر. لا يحصل الشخص المدرج في القائمة المحظورة على تطبيق WhatsApp أو البريد الإلكتروني أو الرسائل النصية القصيرة؛ قم بإدارة القائمة ضمن الدردشات › ☰ › قائمة الحظر.',
  'Kişi hafızası ve arka plan işleri' => 'ذاكرة الاتصال ووظائف الخلفية',
  'Kişi hafızası: asistan kişinin kalıcı bilgilerini (hitap, yakınlarının adı, numaralar, tercihler) hatırlar; süresi dolan sohbetler özetlenir' => 'ذاكرة الاتصال: يتذكر المساعد التفاصيل الدائمة (شكل العنوان وأسماء الأقارب والأرقام والتفضيلات)؛ يتم تلخيص الدردشات منتهية الصلاحية',
  'Sohbet kaç saat sessiz kalınca özetlensin' => 'تلخيص محادثة بعد أن كانت هادئة لمدة (ساعات)',
  'Aynı anda en fazla iş' => 'الحد الأقصى من الوظائف في نفس الوقت',
  'Aynı anda cevap yazılabilecek kişi sayısı. Asistan cevapları her zaman önce gelir; cevap yazılan ya da sırada bekleyen kişi varken özet başlamaz. Her iş bir PHP işçisi kullanır: paylaşımlı hostingde sitelerin toplam işçi sınırının yarısını geçmeyin (ör. 60 işçide 20-30).' => 'كم شخص يمكن الرد عليه في نفس الوقت. تأتي ردود المساعد دائمًا في المقام الأول؛ لا تبدأ الملخصات أثناء الرد على شخص ما أو انتظاره. تستخدم كل وظيفة عامل PHP واحدًا: في الاستضافة المشتركة، ابق أقل من نصف الحد الإجمالي للعمال في مواقعك (على سبيل المثال، 20-30 من 60 عاملاً).',
  'Yalnız cevaplara ayrılan işçi' => 'العمال محفوظة للردود',
  'Bu kadar işçi hiçbir zaman özet ya da hatırlatıcı almaz.' => 'هذا العدد من العمال لا يأخذون ملخصات أو تذكيرات أبدًا.',
  'Özet saatleri' => 'ساعات الملخص',
  'Özetler yalnız bu saatler arasında yapılır (elle "Şimdi özetle" hariç). İkisi aynıysa her saat.' => 'يتم تشغيل الملخصات فقط بين هذه الساعات (باستثناء دليل "التلخيص الآن"). إذا كان كلاهما هو نفسه، في أي وقت.',
  'Kişi sesli mesaj gönderirse asistan sesi metne çevirip cevap versin (metin panelde sistem satırı olarak da görünür)' => 'عندما يرسل شخص ما رسالة صوتية، يقوم المساعد بتحويلها إلى نص والردود (يظهر النص أيضًا في اللوحة كخط نظام)',
  'En uzun ses (sn)' => 'أطول رسالة صوتية (ثانية)',
  'Daha uzun seslerde asistan "ses çok uzun olduğu için dinleyemedik" der.' => 'بالنسبة للرسائل الأطول، يقول المساعد "كانت الرسالة الصوتية طويلة جدًا بالنسبة لنا للاستماع إليها".',
  'Sesli mesaj modeli (isteğe bağlı)' => 'نموذج الرسالة الصوتية (اختياري)',
  'Ses okuyan ucuz model (Gemini Flash Lite)' => 'نموذج صوتي رخيص (Gemini Flash Lite)',
  'Ses okuyan bir OpenRouter modeli olmalı (Claude ses okumaz). OpenRouter anahtarı gerekir.' => 'يجب أن يكون نموذج OpenRouter يقبل الصوت (كلود لا يقبل ذلك). مطلوب مفتاح OpenRouter.',
  'Görseller' => 'الصور',
  'Gerekince asistan görsel (tablo, rapor, şema) çizsin; WhatsApp\'a resim olarak gider, metin ayrıca gider' => 'اسمح للمساعد برسم صورة عندما يكون ذلك مفيدًا (جدول، تقرير، رسم تخطيطي)؛ فإنه يذهب إلى WhatsApp كصورة، ويتم إرسال النص بشكل منفصل',
  'Flux AI görsel çeviricisi kullanılır (Flux AI & MCP › Ayarlar › Görseller).' => 'يتم استخدام عارض الصور Flux AI (Flux AI & MCP ›الإعدادات› الصور).',
  'Sunucuda görsel çevirici yok: Flux AI & MCP › Ayarlar › Görseller\'e Gotenberg adresi girin ya da Imagick (SVG) kurulsun. O zamana kadar asistan görsel çizmez.' => 'لا يوجد عارض صور على الخادم: أدخل عنوان Gotenberg في Flux AI & MCP ›الإعدادات› الصور أو قم بتثبيت Imagick (SVG). وحتى ذلك الحين لا يرسم المساعد الصور.',
  'Flux AI 0.2.0 ya da sonrası kurulunca çalışır.' => 'يعمل بمجرد تثبيت Flux AI 0.2.0 أو الأحدث.',
  'Başkası adına bağış' => 'التبرع نيابة عن شخص ما',
  'Bağış başkası adınaysa ve o kişinin numarası verildiyse (kişi kartı ya da yazılı numara), ödeme onaylanınca sertifika o numaraya da WhatsApp\'tan gitsin' => 'إذا كان التبرع باسم شخص آخر وتم إعطاء رقمه (بطاقة الاتصال أو الرقم المكتوب)، قم أيضًا بإرسال الشهادة إلى هذا الرقم على الواتساب بمجرد الموافقة على الدفع',
  'Sertifikadan önce giden mesaj' => 'الرسالة المرسلة قبل الشهادة',
  'Ardından Flux Certificates\'daki WhatsApp sertifika mesajı gider. Değişkenler: {ad}, {bagisci}, {bagis}, {brand}.' => 'ثم يتم إرسال رسالة شهادة WhatsApp من شهادات Flux. المتغيرات: {ad}, {bagisci}, {bagis}, {brand}.',
  'Kişi isterse asistan hatırlatıcı kurar (ör. "her ay fidan dikimini hatırlat", "her ay son projelerinizi gönderin", "her ay benden bir fidan iste"); zamanı gelince asistan mesajı yazıp gönderir' => 'إذا سأل شخص ما، يقوم المساعد بإعداد تذكير (على سبيل المثال، "ذكرني بزراعة شتلات كل شهر"، "أرسل لي أحدث مشاريعك كل شهر"، "اسألني عن شتلة كل شهر")؛ عندما يحين موعدها، يقوم المساعد بكتابة الرسالة وإرسالها',
  'Saat söylenmezse' => 'عندما لا يعطى الوقت',
  'Kişi başına en fazla' => 'على الأكثر للشخص الواحد',
  'Personel (Flux Roles)' => 'طاقم العمل (أدوار التدفق)',
  'Flux Roles 1.1.0 kurulunca çalışır: numarası Profil › WhatsApp numarası alanına yazılmış kullanıcılar asistanda yetkilerine göre ek araçlar kullanır.' => 'يعمل بمجرد تثبيت Flux roles 1.1.0: يحصل المستخدمون الذين تم تعيين أرقامهم في ملف التعريف › رقم WhatsApp على أدوات مساعدة إضافية بناءً على أذوناتهم.',
  'Personel numarasından yazana asistan yetkisine göre ek araçlar açsın (başkası adına bağış ve ödeme linki, bağışçılarım, genel rapor)' => 'منح أرقام الموظفين أدوات مساعدة إضافية عن طريق الإذن (التبرع نيابة عن شخص لديه رابط الدفع، الجهات المانحة، التقرير العام)',
  'Referansı olduğu bağış ödenince ya da iptal olunca personele WhatsApp bildirimi gitsin' => 'قم بإخطار الموظفين عبر تطبيق WhatsApp عندما يتم دفع أو إلغاء التبرع الذي أحالوه',
  'Personel adına açılan bağışta bağışçıya ilk mesaj' => 'الرسالة الأولى إلى المتبرع بالتبرع يفتحها الموظفون',
  'Merhaba {ad} 🌱 {personel} aracılığıyla {bagis} bağış talebiniz alındı. Ödemeyi aşağıdaki bilgilerle yapabilirsiniz.' => 'مرحبًا {ad}🌱 لقد تم استلام طلب التبرع بـ{bagis} عبر {personel}. يمكنك الدفع بالتفاصيل أدناه.',
  'Ardından ödeme linki ve havale bilgileri gider. Değişkenler: {ad}, {adsoyad}, {personel}, {bagis}.' => 'اتبع رابط الدفع والتفاصيل المصرفية. المتغيرات: {ad}, {adsoyad}, {personel}, {bagis}.',
  'Personelin referansı olduğu bağış ödenip sertifika oluşunca sertifika personele de WhatsApp\'tan gitsin (bağışçıya gittiği gibi)' => 'عند دفع التبرع المحول من أحد الموظفين وإصدار شهاداته، أرسلها إلى الموظف على الواتساب أيضًا (تمامًا مثل المتبرع)',
  'Personele sertifikadan önce giden mesaj' => 'الرسالة المرسلة للموظف قبل الشهادة',
  'Değişkenler: {ad}, {bagisci}, {bagis}, {no}, {brand}.' => 'المتغيرات: {ad}, {bagisci}, {bagis}, {no}, {brand}.',
  'Personel bir bağışın sertifikasını en fazla kaç kez yeniden gönderebilir' => 'كم مرة يمكن للموظفين إعادة إرسال شهادة التبرع',
  'Asistan göndermeden önce kime gideceğini yazıp onay ister. 0: kapalı.' => 'يقوم المساعد بإدراج المستلمين ويطلب التأكيد قبل الإرسال. 0: إيقاف.',
  'Kayıt sorgusunda kod doğrulama' => 'التحقق من الكود لعمليات البحث عن السجلات',
  'Kişi kayıtlarını sorar ve numarası gizliyse (ya da başka numara/e-postayla bağış yaptıysa) verdiği numaraya ya da e-postaya kod gönder; kod doğrulanınca onun kayıtları da gösterilir' => 'عندما يطلب شخص ما سجلاته ويكون رقمه مخفيًا (أو تبرع برقم/بريد إلكتروني آخر)، أرسل رمزًا إلى الرقم أو البريد الإلكتروني الذي يقدمه؛ وبمجرد التحقق منها، تظهر سجلاتها أيضًا',
  'Kod geçerliliği (dk)' => 'صلاحية الكود (دقيقة)',
  'En fazla başarısız deneme' => 'الحد الأقصى للمحاولات الفاشلة',
  'Gönderilemeyen, yanlış ya da süresi dolan kodlar sayılır. Sınırda kişiye aşağıdaki mesaj gider, ekibe haber verilir; asistan diğer sorulara cevap verir ama 24 saat kayıt bilgisi vermez.' => 'الرموز التي لا يمكن إرسالها، يتم احتساب الرموز الخاطئة والرموز منتهية الصلاحية. عند الحد يحصل الشخص على الرسالة أدناه ويتم إخطار الفريق؛ يستمر المساعد في الإجابة على الأسئلة الأخرى ولكنه لا يشارك تفاصيل السجل لمدة 24 ساعة.',
  'Telefona kod' => 'الرمز إلى الهاتف',
  'WhatsApp, gitmezse SMS' => 'WhatsApp، SMS إذا فشل',
  'Yalnız WhatsApp' => 'واتساب فقط',
