  'SMS, Flux Mail\'te SMS bağlantısı (ör. Netgsm) varsa kullanılır.' => 'يتم استخدام الرسائل القصيرة إذا كان لدى Flux Mail اتصال عبر الرسائل القصيرة (مثل Netgsm).',
  'Doğrulama yapılamazsa giden mesaj' => 'رسالة عند فشل التحقق',
  'WhatsApp/SMS kod mesajı' => 'رسالة رمز WhatsApp/SMS',
  'Boşsa varsayılan metin. Değişkenler: {kod}, {dk}, {marka}. E-posta metni Flux Mail › E-posta şablonları\'ndan değişir.' => 'النص الافتراضي إذا كان فارغا. المتغيرات: {kod}، {dk}، {marka}. يتم تحرير نص البريد الإلكتروني في Flux Mail › قوالب البريد الإلكتروني.',
  'Sitedeki içerikler' => 'محتوى الموقع',
  'Asistan sitede yayında olan içeriklerde arama yapabilsin (ör. "fidan dikimi geçen bir gönderiniz var mı")' => 'اسمح للمساعد بالبحث في محتوى الموقع المنشور (على سبيل المثال، "هل لديك مشاركة حول زراعة الأشجار")',
