  'Mesajlar (sırayla)' => 'الرسائل (بالترتيب)',
  '{tur}, {birim} ve {brand} kullanılabilir. Yalnız müşteri mesajı varsa asistan her birine sırayla cevap verir. Asistan mesajı eklerseniz devam senaryosu olur: yazılan geçmiş hazır verilir, asistan yalnız en sondaki müşteri mesajına cevap verir.' => 'يمكن استخدام {tur} و {birim} و {brand}. إذا كانت هناك رسائل العملاء فقط، يقوم المساعد بالرد على كل منها بدوره. إذا قمت بإضافة رسائل مساعد، فسيصبح ذلك سيناريو استمرارًا: يتم تقديم السجل المكتوب كما هو ولا يرد المساعد إلا على آخر رسالة للعميل.',
  'Ör. payment_info, cancel_donation, receipt_check. Bu sitede kapalı araç bakılmaz.' => 'على سبيل المثال معلومات الدفع، إلغاء_التبرع، استلام_التحقق. لم يتم التحقق من الأدوات المعطلة على هذا الموقع.',
