  'Sonda durum' => 'نهاية الحالة',
  'Konuşma bitince test durumuna bakılır (bağış açıldı mı, iptal edildi mi, kod gitti mi…). Bu sitede kapalı araç bakılmaz.' => 'عند انتهاء المحادثة، يتم التحقق من حالة الاختبار (هل تم فتح التبرع، أو إلغاؤه، أو إرسال الرمز...). لم يتم التحقق من الأدوات المعطلة على هذا الموقع.',
