  'Hâlâ Flux Certificates\'daki eski sağlayıcı kullanılıyor; bağlantıyı Flux Mail\'e taşıyıp burada seçin.' => 'لا تزال تستخدم الموفر القديم في شهادات التدفق؛ انقل الاتصال إلى Flux Mail وحدده هنا.',
