  'API adresi, key ve instance bu eklentide girilmiş.' => 'يتم إدخال عنوان URL لواجهة برمجة التطبيقات والمفتاح والمثيل في هذا البرنامج المساعد.',
  '%s: hat durumu' => '%s: حالة الخط',
  'Telefon bağlı (son bilgi %s).' => 'الهاتف متصل (شوهد آخر مرة %s).',
  'Henüz denenmedi. "Bağlantıyı test et" düğmesine basın.' => 'لم يتم اختباره بعد. اضغط على "اختبار الاتصال".',
  'Telefon bağlı değil (durum: %1$s, %2$s). "QR ile bağla" ile yeniden bağlayın.' => 'الهاتف غير متصل (الحالة: %1$s، %2$s). أعد الاتصال بـ "الاتصال بـ QR".',
  '%s: Evolution API sürümü' => '%s: إصدار Evolution API',
  'Evolution API %s kullanılıyor. Gizli numaralı (@lid) kişilere cevap gitmeyebilir; sunucuyu 2.3 veya üstüne güncelleyin.' => 'Evolution API %s قيد الاستخدام. قد تفشل الردود على جهات الاتصال ذات الرقم المخفي (@lid)؛ تحديث الخادم إلى 2.3 أو الأحدث.',
  '%s: webhook (gelen mesajlar)' => '%s: خطاف الويب (الرسائل الواردة)',
  'Evolution\'dan hiç olay gelmedi; gelen mesajlar panele düşmez. "Webhook\'u kur" düğmesine basın.' => 'لم تصل أي أحداث من التطور؛ لن تظهر الرسائل الواردة في اللوحة. اضغط على "إعداد خطاف الويب".',
  'Son olay %s geldi. Hat sessiz olabilir; emin olmak için kendinize mesaj atın ya da webhook\'u yeniden kurun.' => 'الحدث الأخير وصل %s. قد يكون الخط هادئًا فحسب؛ أرسل لنفسك رسالة أو قم بإعداد خطاف الويب مرة أخرى للتأكد.',
  'Son olay %s geldi.' => 'الحدث الأخير وصل %s.',
  'Flux Mail entegrasyonu' => 'تكامل البريد الجريان',
  'Etkin: WhatsApp bağlantıları İletişim › Bağlantılar\'dan alınır.' => 'نشط: اتصالات WhatsApp مأخوذة من الاتصالات › الاتصالات.',
  'Flux Mail etkin değil; bağlantılar Flux Certificates\'dan ya da bu eklentiden alınır.' => 'Flux Mail غير نشط؛ يتم أخذ الاتصالات من شهادات Flux أو من هذا البرنامج المساعد.',
  'Flux Certificates entegrasyonu' => 'تكامل شهادات التدفق',
  'Etkin: sohbetten sertifika oluşturulup gönderilebilir.' => 'نشط: يمكن إنشاء الشهادات وإرسالها من الدردشات.',
  'Flux Certificates etkin değil; sohbetten sertifika işlemleri kapalı.' => 'شهادات التدفق غير نشطة؛ إجراءات الشهادة في الدردشات متوقفة.',
  'Flux Donate entegrasyonu' => 'تدفق التبرع التكامل',
  'Etkin: sohbetten bağış kaydı, dekont eşleştirme ve asistan kullanılabilir.' => 'نشط: تتوفر سجلات التبرعات ومطابقة الإيصالات والمساعد من الدردشات.',
  'Flux Donate etkin değil; bağış kaydı, dekont eşleştirme ve bağış asistanı kapalı.' => 'Flux Donate غير نشط؛ سجلات التبرعات ومطابقة الإيصالات ومساعد التبرعات متوقفة.',
  'Flux AI & MCP eklentisi kurulu değil; yapay zekâ özellikleri (öneri, asistan, dekont okuma, sesli mesaj, özet) kapalı. Flux AI\'yi kurup anahtarı oraya girin.' => 'لم يتم تثبيت البرنامج المساعد Flux AI & MCP؛ ميزات الذكاء الاصطناعي (الاقتراحات، المساعد، قراءة الإيصالات، الرسائل الصوتية، الملخصات) متوقفة. قم بتثبيت Flux AI وأدخل المفتاح هناك.',
  'Flux AI\'de anahtar girilmemiş; mesaj önerisi ve asistan kapalı.' => 'لم يتم إدخال أي مفتاح في Flux AI؛ اقتراحات الرسائل والمساعد متوقفان.',
  'Anahtar var ama model seçilmemiş.' => 'تم حفظ المفتاح ولكن لم يتم تحديد نموذج.',
  'Seçili model (%s) için Flux AI\'de sağlayıcının anahtarı girilmemiş.' => 'لم يتم إدخال أي مفتاح موفر في Flux AI للنموذج المحدد (%s).',
  'Anahtar kayıtlı, model: %s. Canlı deneme için "Bağlantıyı test et".' => 'تم حفظ المفتاح، الموديل: %s. استخدم "اختبار الاتصال" لإجراء فحص مباشر.',
  'Bağış asistanı' => 'مساعد التبرع',
  'Kapalı.' => 'إيقاف.',
  'Yapay zekâ anahtarı veya modeli eksik.' => 'مفتاح الذكاء الاصطناعي أو النموذج مفقود.',
  'Açık ama konuşmuyor: ' => 'قيد التشغيل ولكن لا يرد:',
  'Açık. Sunulan bağış türleri: %s.' => 'على. أنواع التبرعات المقدمة: %s.',
  '%s araç (tools) desteklemiyor; asistan için araç destekli bir model seçin.' => '%s لا يدعم الأدوات؛ اختر نموذجًا قادرًا على استخدام الأدوات للمساعد.',
  'Dekont okuma modeli' => 'نموذج قراءة الإيصال',
  '%s görsel okuyamıyor; dekont ön kontrolü çalışmaz. Görsel destekli bir dekont okuma modeli seçin.' => 'لا يستطيع %s قراءة الصور؛ لن يعمل الفحص المسبق للاستلام. اختر نموذجًا لقراءة الإيصالات مزودًا بالصور.',
  'Asistanın ödeme bilgileri' => 'تفاصيل الدفع للمساعد',
  'Alıcı adı ve IBAN tanımlı.' => 'اسم المستلم ومجموعة IBAN.',
  'Alıcı adı veya IBAN eksik; onaydan sonra havale bilgisi gönderilemez.' => 'اسم المستلم أو رقم IBAN مفقود؛ لا يمكن إرسال التفاصيل المصرفية بعد التأكيد.',
  'Bağış sayfası linki' => 'رابط صفحة التبرع',
  'Bağış sayfası bulunamadı; asistan link göndermez.' => 'لم يتم العثور على صفحة التبرع؛ لن يرسل المساعد رابطًا.',
  'Arka plan istekleri' => 'طلبات الخلفية',
  'Site kendine arka plan isteği atamadı (%1$s: %2$s). Sıradaki cevaplar ve benchmark yavaş ilerleyebilir; güvenlik eklentisi ya da sunucu güvenlik duvarı /wp-json/flx-chat/ isteklerini engelliyor olabilir.' => 'تعذر على الموقع إرسال طلب خلفية إلى نفسه (%1$s: %2$s). الردود الموجودة في قائمة الانتظار وقد يتحرك المؤشر ببطء؛ قد يقوم مكون إضافي للأمان أو جدار حماية الخادم بحظر طلبات /wp-json/flx-chat/.',
  'hata' => 'خطأ',
  'uyarı' => 'تحذير',
  'tamam' => 'حسنا',
  '{marka} doğrulama kodunuz: {kod}' => 'رمز التحقق {marka} الخاص بك: {kod}',
  'Kod {dk} dakika geçerlidir. Bu kodu WhatsApp\'ta bizimle olan sohbete yazın. Bu isteği siz yapmadıysanız dikkate almayın.' => 'الرمز صالح لمدة {dk} دقيقة. اكتبه في دردشة الواتساب الخاصة بك معنا. إذا لم تطلب ذلك، تجاهل هذه الرسالة.',
  'Bir sıkıntı oldu, ekibimiz en kısa sürede sizinle iletişime geçecek 🌱 Bu arada başka bir sorunuz olursa yazabilirsiniz.' => 'حدث خطأ ما؛ سيقوم فريقنا بالتواصل معك في أقرب وقت ممكن 🌱 وفي الوقت نفسه، لا تتردد في سؤال أي شيء آخر.',
  'Doğrulama denemesi başarısız (%1$d/%2$d): %3$s' => 'فشلت محاولة التحقق (%1$d/%2$d): %3$s',
  'Kişi kayıtlarını görmek istedi, doğrulama yapılamadı; ekipten biri iletişime geçmeli' => 'أراد الشخص رؤية سجلاته ولكن لم يتمكن من التحقق منها؛ يجب أن يتصل بك أحد أعضاء الفريق',
  'e-posta gönderilemedi (Flux Mail › SMTP ayarlarını kontrol edin)' => 'تعذر إرسال البريد الإلكتروني (تحقق من Flux Mail › إعدادات SMTP)',
  'Asistan %1$s için doğrulama kodu gönderdi (%2$s).' => 'أرسل المساعد رمز التحقق لـ%1$s(%2$s).',
  'kodun süresi doldu' => 'انتهت صلاحية الرمز',
  'yanlış kod' => 'رمز خاطئ',
  'Kişi %s için kodu doğruladı; kayıt sorgusuna eklendi.' => 'قام الشخص بالتحقق من رمز %s؛ تتم إضافته إلى عمليات البحث عن السجلات الخاصة بهم.',
  'Claude modelleri ses okuyamaz; Ayarlar › Yapay zekâ › Sesli mesaj modelinden ses okuyan bir OpenRouter modeli seçin.' => 'لا تستطيع نماذج كلود قراءة الصوت؛ اختر طراز OpenRouter مزودًا بإمكانيات الصوت في الإعدادات › AI › نموذج الرسالة الصوتية.',
  'Ses metne çevrilemedi.' => 'لا يمكن نسخ الصوت.',
  'Ses dosyası okunamadı.' => 'لا يمكن قراءة الملف الصوتي.',
  'Sesli mesaj (%1$s) metne çevrildi: %2$s' => 'الرسالة الصوتية (%1$s) مكتوبة: %2$s',
  'Sesli mesaj (%1$s) dinlenemedi: %2$s' => 'لا يمكن معالجة الرسالة الصوتية (%1$s): %2$s',
  'Resmi WhatsApp Cloud API hattında bu işlem yok.' => 'هذا الإجراء غير متاح على خط WhatsApp Cloud API الرسمي.',
  'WhatsApp 24 saat kuralı: kişi son 24 saatte yazmadığı için Cloud API serbest mesaj göndermiyor; yalnız onaylı şablon gider. Kişi yazınca yeniden deneyin.' => 'قاعدة WhatsApp على مدار 24 ساعة: لم تكتب جهة الاتصال خلال الـ 24 ساعة الماضية، لذا لن ترسل Cloud API رسالة ذات شكل حر؛ يمكن إرسال القالب المعتمد فقط. حاول مرة أخرى بمجرد الكتابة.',
  'Cloud API hattı için Flux Mail 1.10.0 veya üstü gerekli.' => 'يحتاج خط Cloud API إلى Flux Mail 1.10.0 أو إصدار أحدث.',
  'Cloud API bu adrese (gizli numara ya da grup) gönderemez.' => 'لا يمكن لـ Cloud API الإرسال إلى هذا العنوان (رقم أو مجموعة مخفية).',
  'Cloud API hesabına ulaşılamadı (İletişim › Bağlantılar).' => 'تعذر الوصول إلى حساب Cloud API (الاتصالات ›).',
  'Cloud API hattında QR yok; hesap İletişim › Bağlantılar\'da kurulur.' => 'لا يحتوي خط Cloud API على رمز QR؛ تم إعداد الحساب في Életişim › Connections.',
  'Dosya hazırlanamadı.' => 'لا يمكن تحضير الملف.',
  'Flux AI görsel desteği yok.' => 'لا يوجد لدى Flux AI دعم للصور.',
  'Görsel çevrilemedi.' => 'لا يمكن تقديم الصورة.',
  'Asistanın görseli gönderilemedi: ' => 'لا يمكن إرسال صورة المساعد:',
  'Merhaba {first_name}, bağış kaydınızı oluşturduk: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . '{bank}' . chr(10) . '' . chr(10) . 'Ödemeyi yaptıktan sonra dekontu buradan gönderebilirsiniz. Teşekkür ederiz.' => 'مرحبًا {first_name}، لقد أنشأنا سجل التبرع الخاص بك: {donation}، إجمالي {amount}.{bank} بعد الدفع، يمكنك إرسال الإيصال هنا. شكرًا لك.',
  'Merhaba {first_name}, bağışınız kaydedildi: {donation}, toplam {amount}.' . chr(10) . '' . chr(10) . 'Desteğiniz için teşekkür ederiz.' => 'مرحبًا {first_name}، تم تسجيل تبرعك: {donation}، إجمالي {amount}.' . chr(10) . '' . chr(10) . 'شكرا لدعمكم.',
  'Bu senaryoyu oynatacak eklenti kapalı.' => 'البرنامج المساعد الذي سيقوم بتشغيل هذا السيناريو غير نشط.',
  'Bu kullanıcının personel araçları yetkisi yok.' => 'لا يسمح لهذا المستخدم باستخدام أدوات الموظفين.',
  '%1$s bu sohbeti personel olarak bağladı: %2$s' => 'ربطت %1$s هذه الدردشة بالموظف %2$s',
  '%s sohbetin personel bağlantısını kaldırdı' => 'قام %s بإزالة رابط الموظفين الخاص بهذه الدردشة',
  'Sohbet personele bağlandı' => 'الدردشة مرتبطة بالموظف',
  'Personel bağlantısı kaldırıldı' => 'تمت إزالة رابط الموظفين',
  '— Personel değil —' => '- ليس موظفين -',
  'WhatsApp bu kişinin numarasını gizliyor, asistan personeli numaradan tanıyamaz. Bu kişi ekibinizdense buradan bağlayın; asistan personel araçlarını açar.' => 'يقوم WhatsApp بإخفاء رقم هذا الشخص، لذلك لا يستطيع المساعد التعرف على الموظفين من خلال الرقم. إذا كان هذا الشخص ضمن فريقك، قم بربطه هنا وسيقوم المساعد بفتح أدوات الموظفين.',
  'Asistan personeli Flux Roles profilindeki numaradan tanır. Numara eşleşmiyorsa buradan bağlayabilirsiniz; numarası bilinen sohbette numara önceliklidir.' => 'يتعرف المساعد على الموظفين من خلال الرقم الموجود في ملف تعريف Flux الأدوار الخاص بهم. إذا كان الرقم غير متطابق، يمكنك ربطهم هنا؛ في الدردشة مع رقم معروف يأتي الرقم أولا.',
  'Bu kanal şu an kullanılamıyor.' => 'هذه القناة غير متوفرة حاليا.',
  'Site sohbeti' => 'دردشة الموقع',
  'WhatsApp, site sohbeti ve diğer kanallardan gelen tüm mesajlar burada canlı görünür. Soldan bir sohbet seçin.' => 'جميع الرسائل من الواتساب ودردشة الموقع والقنوات الأخرى تظهر هنا مباشرة. اختر الدردشة على اليسار.',
  'WhatsApp (Evolution API) çağrı merkezi: gelen ve giden mesajları canlı görün, yeni sohbet başlatın, hazır cevaplar, etiketler, atama, dahili notlar, otomatik yanıtlar; sohbetten bağış (Flux Donate) ve sertifika (Flux Certificates) kaydı, dekont eşleştirme. OpenRouter ile yapay zekâ cevap önerisi ve otomatik bağış asistanı.' => 'مركز اتصال WhatsApp (Evolution API): شاهد الرسائل الواردة والصادرة المباشرة، وابدأ محادثة جديدة، والردود الجاهزة، والعلامات، والمهمة، والملاحظات الداخلية، والردود التلقائية؛ التبرع (Flux Donate) وتسجيل الشهادة (Flux الشهادات) من الدردشة، ومطابقة الاستلام. اقتراح استجابة الذكاء الاصطناعي ومساعد التبرع التلقائي مع OpenRouter.',
  'WhatsApp (Evolution API) call center: see live incoming and outgoing messages, start new chat, canned replies, tags, assignment, internal notes, auto-replies; Donation (Flux Donate) and certificate (Flux Certificates) registration from chat, receipt matching. Artificial intelligence response suggestion and automatic donation assistant with OpenRouter.' => 'مركز اتصال WhatsApp (Evolution API): شاهد الرسائل الواردة والصادرة المباشرة، وابدأ محادثة جديدة، والردود الجاهزة، والعلامات، والمهمة، والملاحظات الداخلية، والردود التلقائية؛ التبرع (Flux Donate) وتسجيل الشهادة (Flux الشهادات) من الدردشة، ومطابقة الاستلام. اقتراح استجابة الذكاء الاصطناعي ومساعد التبرع التلقائي مع OpenRouter.',
  'Hide' => 'إخفاء',
  'Show' => 'إظهار',
  'Deleted for everyone' => 'تم الحذف لدى الجميع',
  'Hidden in the panel' => 'مخفية في اللوحة',
  'Delete for everyone' => 'حذف لدى الجميع',
  'Hide in the panel only' => 'إخفاء في اللوحة فقط',
  'WhatsApp doesn\'t allow deleting a received message for everyone; it stays on the contact\'s phone and is only hidden in the panel.' => 'لا يسمح واتساب بحذف رسالة مستلمة لدى الجميع؛ تبقى على هاتف جهة الاتصال وتُخفى في اللوحة فقط.',
  'Delete for everyone is turned off in the settings; the message is only hidden in the panel and stays on the contact\'s phone.' => 'الحذف لدى الجميع معطّل في الإعدادات؛ تُخفى الرسالة في اللوحة فقط وتبقى على هاتف جهة الاتصال.',
  'This channel doesn\'t support delete for everyone; the message is only hidden in the panel and stays on the contact\'s phone.' => 'هذه القناة لا تدعم الحذف لدى الجميع؛ تُخفى الرسالة في اللوحة فقط وتبقى على هاتف جهة الاتصال.',
  'The time limit for delete for everyone has passed (WhatsApp allows about {h} hours after sending). The message stays on the contact\'s phone and is only hidden in the panel.' => 'انتهت مهلة الحذف لدى الجميع (يسمح واتساب بنحو {h} ساعة بعد الإرسال). تبقى الرسالة على هاتف جهة الاتصال وتُخفى في اللوحة فقط.',
  'Only the sender or an administrator can delete this message for everyone; you can hide it in the panel.' => 'لا يمكن حذف هذه الرسالة لدى الجميع إلا للمرسل أو المسؤول؛ يمكنك إخفاؤها في اللوحة.',
  'If deleted for everyone, the message also turns into "This message was deleted" on the contact\'s phone. Time left: about {n} hours.' => 'عند الحذف لدى الجميع تظهر الرسالة على هاتف جهة الاتصال أيضًا كـ "تم حذف هذه الرسالة". الوقت المتبقي: نحو {n} ساعة.',
  'Deleted messages are kept on the server: the chat shows a "This message was deleted" line and the team can click it to see the content. AI does not read deleted messages.' => 'تُحفظ الرسائل المحذوفة على الخادم: يظهر في المحادثة سطر "تم حذف هذه الرسالة" ويمكن للفريق النقر عليه لرؤية المحتوى. الذكاء الاصطناعي لا يقرأ الرسائل المحذوفة.',
  'Message not found.' => 'لم يتم العثور على الرسالة.',
  'This message was already deleted.' => 'تم حذف هذه الرسالة مسبقًا.',
  'Only the sender or an administrator can delete this message for everyone.' => 'لا يمكن حذف هذه الرسالة لدى الجميع إلا للمرسل أو المسؤول.',
  'This message can\'t be deleted for everyone on this channel. You can hide it in the panel instead.' => 'لا يمكن حذف هذه الرسالة لدى الجميع في هذه القناة. يمكنك إخفاؤها في اللوحة بدلًا من ذلك.',
  'The time limit for deleting for everyone has passed. You can hide it in the panel instead.' => 'انتهت مهلة الحذف لدى الجميع. يمكنك إخفاؤها في اللوحة بدلًا من ذلك.',
  'WhatsApp did not delete the message.' => 'لم يحذف واتساب الرسالة.',
  'Delete for everyone time limit (hours)' => 'مهلة الحذف لدى الجميع (ساعات)',
  'WhatsApp lets you delete a sent message for everyone only for about 2 days and 12 hours (60 hours). After this limit, or for received messages, the message is only hidden in the panel: it stays on the contact\'s phone. 0 turns off delete for everyone. Deleted messages are never removed from the server; the team can still open them.' => 'يسمح واتساب بحذف رسالة مرسلة لدى الجميع خلال نحو يومين و12 ساعة (60 ساعة) فقط. بعد هذه المهلة، أو في الرسائل المستلمة، تُخفى الرسالة في اللوحة فقط وتبقى على هاتف جهة الاتصال. القيمة 0 توقف الحذف لدى الجميع. لا تُزال الرسائل المحذوفة من الخادم أبدًا؛ ويمكن للفريق فتحها.',
  'Last update request %1$s. While the panel is open it checks for new messages every %2$d s (3 s while a reply is streaming, up to 15 s when nothing changes) and once a minute in a background tab.' => 'طلب التحديث الأخير %1$s. عندما تكون اللوحة مفتوحة تتحقق من الرسائل الجديدة كل %2$d ث (3 ث أثناء بث الرد، وحتى 15 ث إن لم يتغير شيء) ومرة كل دقيقة في علامة تبويب خلفية.',
  'The open tab checks for new messages at this interval (10 recommended), every 3 s while a reply is streaming, and up to 15 s when nothing changes. A background tab checks once a minute. Errors back off up to 60 s.' => 'تتحقق علامة التبويب المفتوحة من الرسائل الجديدة في هذه الفترة (يُوصى بـ 10)، كل 3 ث أثناء بث الرد، وحتى 15 ث إن لم يتغير شيء. علامة التبويب الخلفية تتحقق مرة كل دقيقة. عند الأخطاء تمتد المهلة حتى 60 ث.',
  'Flux Donate is not active.' => 'Flux Donate غير مفعّل.',
  'Donor\'s earlier referral' => 'مُحيل المتبرع السابق',
