  'Show less' => 'عرض أقل',
  'Show all ({n})' => 'عرض الكل ({n})',
  'Filled from donation and certificate records (one-off update)' => 'تم الملء من سجلات التبرعات والشهادات (تحديث لمرة واحدة)',
  'Name given by the sending record' => 'الاسم من السجل المُرسِل',
  'Filled from donation and certificate records' => 'تم الملء من سجلات التبرعات والشهادات',
  'The contact said their name in the chat' => 'ذكر جهة الاتصال اسمه في المحادثة',
  'The contact corrected their name in the chat' => 'صحّح جهة الاتصال اسمه في المحادثة',
  'The contact gave their full name in the chat' => 'ذكر جهة الاتصال اسمه الكامل في المحادثة',
  'The assistant updated the reminder: %1$s (%2$s)' => 'حدّث المساعد التذكير: %1$s (%2$s)',
  'The assistant marked the chat as completed (the person said goodbye). It continues normally if they write again.' => 'وضع المساعد علامة «مكتملة» على المحادثة (ودّع الشخص). إذا كتب مجددًا تستمر المحادثة بشكل طبيعي.',
  'Let the assistant react to messages with an emoji (👍 for "okay", 🤲 for thanks and prayers); once goodbyes are said it reacts instead of writing another farewell' => 'السماح للمساعد بالتفاعل مع الرسائل برمز تعبيري (👍 لـ«تمام»، 🤲 للشكر والدعاء)؛ وبعد الوداع يتفاعل بدلًا من كتابة وداع آخر',
  'same person and donation, not a copy' => 'الشخص نفسه والتبرع نفسه، ليست نسخة مكررة',
  'Closing, reactions and reminders' => 'الإنهاء والتفاعلات والتذكيرات',
  'Chat already marked completed (goodbyes said)' => 'المحادثة معلَّمة مسبقًا كمكتملة (تم الوداع)',
  'Site search returns a sample event with a location' => 'يعيد بحث الموقع فعالية تجريبية لها موقع',
  'Chat marked completed' => 'تم تعليم المحادثة كمكتملة',
  'Emoji reaction left' => 'تم ترك تفاعل برمز تعبيري',
  'No text reply to the last message' => 'لا رد نصي على الرسالة الأخيرة',
  'Reminder is one-time' => 'التذكير لمرة واحدة',
  'Exactly one reminder' => 'تذكير واحد بالضبط',
  '(no text, reacted to the message: {e})' => '(بلا نص، تفاعل مع الرسالة: {e})',
  '(no text: the chat is completed, stayed silent)' => '(بلا نص: المحادثة مكتملة، لم يُرسل رد)',
  '(reacted to the message: {e})' => '(تفاعل مع الرسالة: {e})',
  'Reminder request: set at once' => 'طلب تذكير: يُضبط فورًا',
  'Event location and time' => 'مكان الفعالية ووقتها',
  'Continuation: own receipt sent again, asks if it arrived' => 'متابعة: أعاد إرسال إيصاله ويسأل هل وصل',
  'Thanks after help: one short farewell' => 'شكر بعد المساعدة: وداع قصير واحد',
  'Goodbye loop: no repeated farewells' => 'حلقة الوداع: لا وداع متكرر',
  'New topic after goodbye gets a normal reply' => 'موضوع جديد بعد الوداع يُجاب عليه بشكل طبيعي',
  'Question after goodbye is answered' => 'السؤال بعد الوداع يُجاب عليه',
  'Short "okay" after goodbye: reaction only' => '«تمام» قصيرة بعد الوداع: تفاعل فقط',
  'Continuation: prayer gets a prayer reaction' => 'متابعة: الدعاء يُقابَل بتفاعل دعاء',
  'Continuation: "you will remind me" sets the reminder at once' => 'متابعة: «ذكّروني» تضبط التذكير فورًا',
  'Changes the day afterwards: same reminder updated' => 'يغيّر اليوم لاحقًا: يُحدَّث التذكير نفسه',
  'Monthly reminder turned into one-time' => 'تذكير شهري يتحول إلى تذكير لمرة واحدة',
 ),
);
